const isProduction = process.env.NODE_ENV === "production";

function safeErrorMessage(error: unknown, fallback: string): string {
  if (isProduction) return fallback;
  return error instanceof Error ? error.message : String(error);
}

function getAppBaseUrl(req: Request): string {
  if (process.env.APP_BASE_URL) return process.env.APP_BASE_URL.replace(/\/+$/, "");
  const proto = req.headers["x-forwarded-proto"] || req.protocol || "http";
  const host = req.headers["x-forwarded-host"] || req.headers.host || "localhost:5000";
  return `${proto}://${host}`;
}

async function getCompanyESignConfig(companyId: string): Promise<CompanyESignConfig | undefined> {
  const apiKeys = await storage.getProductApiKeys(companyId);
  const docusignKey = apiKeys.find(k => k.productName === "docusign" && k.isActive);
  const acrobatKey = apiKeys.find(k => k.productName === "acrobat_sign" && k.isActive);
  if (!docusignKey && !acrobatKey) return undefined;

  const config: CompanyESignConfig = {};
  if (docusignKey) {
    try {
      config.docusign = JSON.parse(docusignKey.apiKey);
    } catch { /* fall back to env vars */ }
  }
  if (acrobatKey) {
    try {
      config.acrobat_sign = JSON.parse(acrobatKey.apiKey);
    } catch { /* fall back to env vars */ }
  }
  return Object.keys(config).length > 0 ? config : undefined;
}

const resolvedUploadDir = process.env.UPLOAD_DIR || path.join(process.cwd(), "uploads");
const uploadStorage = multer.diskStorage({
  destination: (_req, _file, cb) => cb(null, resolvedUploadDir),
  filename: (_req, file, cb) => {
    const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
    cb(null, uniqueSuffix + path.extname(file.originalname));
  },
});
const upload = multer({
  storage: uploadStorage,
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (_req, file, cb) => {
    const allowed = /\.(jpg|jpeg|png|gif|svg|webp|ico)$/i;
    if (allowed.test(path.extname(file.originalname))) cb(null, true);
    else cb(new Error("Only image files are allowed"));
  },
});
const documentUpload = multer({
  storage: uploadStorage,
  limits: { fileSize: 10 * 1024 * 1024 },
  fileFilter: (_req, file, cb) => {
    const allowed = /\.(jpg|jpeg|png|gif|svg|webp|pdf|doc|docx)$/i;
    if (allowed.test(path.extname(file.originalname))) cb(null, true);
    else cb(new Error("Only image and document files are allowed"));
  },
});

function computeFileSha256(filePath: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash("sha256");
    const stream = fs.createReadStream(filePath);
    stream.on("data", (chunk: Buffer | string) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
    stream.on("error", reject);
  });
}

function getWeekStart(dateStr: string): string {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  const day = dt.getDay();
  dt.setDate(dt.getDate() - day);
  return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
}

function getWeekEnd(dateStr: string): string {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  const day = dt.getDay();
  dt.setDate(dt.getDate() + (6 - day));
  return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
}

/** Routes accessible during the MFA enrollment grace period (before a user completes enrollment). */
const MFA_ENROLLMENT_ALLOWED_PATHS = new Set([
  "/api/auth/me",
  "/api/auth/logout",
  "/api/auth/mfa/status",
  "/api/auth/mfa/enroll",
  "/api/auth/mfa/confirm",
]);

function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (!req.session?.userId) {
    return res.status(401).json({ message: "Not authenticated" });
  }
  // If MFA enrollment is required for this session, only permit MFA setup endpoints.
  if (req.session.mfaEnrollmentRequired) {
    const path = req.path.split("?")[0];
    if (!MFA_ENROLLMENT_ALLOWED_PATHS.has(path)) {
      return res.status(403).json({
        mfaEnrollmentRequired: true,
        message: "You must complete MFA enrollment before accessing this resource.",
      });
    }
  }
  next();
}

/**
 * Expand a role to its effective legacy aliases for backward-compatible role checks.
 * New explicit platform/tenant roles map to the legacy strings used in existing guards.
 *
 * Critical: platform_* roles are NOT tenant admins — they bypass tenant checks only
 * for platform-console operations. For tenant-scoped API routes they are treated as
 * super-admins so that platform support staff can assist tenants.
 */
function expandRoleForGuard(role: string): string[] {
  if (role === "platform_super_admin" || role === "platform_admin") {
    return ["admin", "manager", "supervisor", role];
  }
  if (role === "system_admin") {
    return ["admin", "system_admin"];
  }
  if (role === "platform_support" || role === "platform_implementation") {
    return ["admin", "manager", role];
  }
  if (["tenant_owner", "tenant_admin", "tenant_hr_admin", "tenant_payroll_admin", "tenant_finance_admin"].includes(role)) {
    return ["admin", role];
  }
  if (["tenant_manager", "tenant_supervisor"].includes(role)) {
    return ["manager", "supervisor", role];
  }
  return [role];
}

function requireRole(...roles: string[]) {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user) {
      return res.status(401).json({ message: "User not found" });
    }
    // Expand the user's role to include legacy aliases so new role names work with
    // existing requireRole("admin") / requireRole("manager") guards throughout the codebase.
    const effectiveRoles = expandRoleForGuard(user.role || "");
    if (!roles.some(r => effectiveRoles.includes(r))) {
      return res.status(403).json({ message: "Insufficient permissions" });
    }
    next();
  };
}

/**
 * Middleware that requires an explicit platform-scoped role.
 * Tenant admins — including legacy "admin" with a companyId — are rejected.
 * Used to protect platform-only API endpoints.
 */
function requirePlatformRole() {
  const PLATFORM_ROLES = [
    "platform_super_admin", "platform_admin", "platform_sales",
    "platform_implementation", "platform_support", "platform_billing", "platform_auditor",
  ];
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user) {
      return res.status(401).json({ message: "User not found" });
    }
    if (!PLATFORM_ROLES.includes(user.role || "")) {
      return res.status(403).json({ message: "Platform Console access required" });
    }
    next();
  };
}

function requireSuperAdmin() {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user || user.role !== "platform_super_admin") {
      return res.status(403).json({ message: "platform_super_admin role required" });
    }
    next();
  };
}

function blockDemoWrites(req: Request, res: Response, next: NextFunction) {
  if (req.session?.isDemo && req.method !== "GET") {
    return res.status(403).json({ message: "Demo mode is read-only. Sign up for a free trial to make changes." });
  }
  next();
}

/**
 * Role-check helpers for inline data-level authorization inside route handlers.
 * These recognize both legacy strings and the new explicit role names.
 */
function isAdminRole(role: string | null | undefined): boolean {
  if (!role) return false;
  return ["admin", "platform_super_admin", "platform_admin", "tenant_owner",
    "tenant_admin", "tenant_hr_admin", "tenant_payroll_admin", "tenant_finance_admin",
  ].includes(role);
}

function isManagerRole(role: string | null | undefined): boolean {
  if (!role) return false;
  return isAdminRole(role) || ["manager", "supervisor", "tenant_manager", "tenant_supervisor",
    "platform_support", "platform_implementation",
  ].includes(role);
}

// Returns true for any platform-scoped role (platform_super_admin, platform_admin, etc.)
// Platform users should never be force-scoped to a single company's data.
function isPlatformUser(role: string | null | undefined): boolean {
  if (!role) return false;
  return role.startsWith("platform_");
}

async function getSessionCompanyId(req: Request): Promise<string | null> {
  if (!req.session?.userId) return null;
  const user = await storage.getUser(req.session.userId);
  return user?.companyId || null;
}

function enforceCompanyScope(source: "query" | "body" = "query") {
  return async (req: Request, res: Response, next: NextFunction) => {
    const sessionCompanyId = await getSessionCompanyId(req);
    if (!sessionCompanyId) return res.status(401).json({ message: "Not authenticated" });
    const requestedCompanyId = source === "query" ? (req.query.companyId as string) : req.body?.companyId;
    if (requestedCompanyId && requestedCompanyId !== sessionCompanyId) {
      return res.status(403).json({ message: "Access denied: company mismatch" });
    }
    (req as any)._companyId = sessionCompanyId;
    next();
  };
}

