async function requireActiveSubscription(req: Request, res: Response, next: NextFunction) {
  if (!req.session?.userId) return next();
  try {
    const user = await storage.getUser(req.session.userId!);
    if (!user?.companyId) return next();
    const rows = await db.execute(sql`SELECT subscription_status, trial_end, grace_period_end FROM companies WHERE id = ${user.companyId}`);
    if (rows.rows.length === 0) return next();
    const company = rows.rows[0] as any;
    const status = company.subscription_status;
    if (status === "suspended" || status === "canceled") {
      return res.status(403).json({
        message: "Account suspended. Please resolve your billing to restore access.",
        reason: "tenant_suspended",
        subscriptionStatus: status,
      });
    }
    if (status === "trial_expired") {
      return res.status(403).json({ message: "Your subscription is inactive. Please upgrade to continue." });
    }
    if (status === "grace_period") {
      const gracePeriodEnd = company.grace_period_end ? new Date(company.grace_period_end) : null;
      if (gracePeriodEnd && new Date() > gracePeriodEnd) {
        await db.execute(sql`UPDATE companies SET subscription_status = 'suspended', billing_active = FALSE WHERE id = ${user.companyId}`);
        return res.status(403).json({
          message: "Your grace period has expired. Account is now suspended. Please resolve billing to restore access.",
          reason: "tenant_suspended",
          subscriptionStatus: "suspended",
        });
      }
      return next();
    }
    if (status === "trial_active" && company.trial_end) {
      const trialEnd = new Date(company.trial_end);
      if (new Date() > trialEnd) {
        await db.execute(sql`UPDATE companies SET subscription_status = 'trial_expired', trial_used = TRUE WHERE id = ${user.companyId}`);
        return res.status(403).json({ message: "Your trial has expired. Please upgrade to continue." });
      }
    }
    next();
  } catch (_e) {
    return res.status(503).json({ message: "Unable to verify subscription status. Please try again." });
  }
}

// ── YTD deduplication helper ──────────────────────────────────────────────────
// If multiple finalized runs exist for the same company + pay period, only one
// should count toward YTD.  Preference order: "paid" > "processed"; within
// the same status the most recently processed run (latest processedAt) wins.
type RunLike = { id: string; periodStart: string; periodEnd: string; status: string; processedAt?: Date | string | null; payDate?: string | null };
function deduplicateByPeriod<T extends RunLike>(runs: T[]): T[] {
  const best = new Map<string, T>();
  for (const r of runs) {
    const key = `${r.periodStart}::${r.periodEnd}`;
    const prev = best.get(key);
    if (!prev) { best.set(key, r); continue; }
    const rankStatus = (s: string) => s === "paid" ? 2 : s === "processed" ? 1 : 0;
    const rRank = rankStatus(r.status);
    const pRank = rankStatus(prev.status);
    if (rRank > pRank) { best.set(key, r); continue; }
    if (rRank === pRank) {
      const rAt = r.processedAt ? new Date(r.processedAt).getTime() : 0;
      const pAt = prev.processedAt ? new Date(prev.processedAt).getTime() : 0;
      if (rAt > pAt) best.set(key, r);
    }
  }
  return [...best.values()];
}

// ── Pay-period resolution helper ───────────────────────────────────────────────
// Given a company's active PayPeriodSchedule and a payDate string (YYYY-MM-DD),
// computes the covered periodStart and periodEnd dates.
// transactionDayOffset: days between periodEnd and payDate (default 4 for weekly
// Sun–Sat / Wednesday payday). Default of 3 is kept only for non-weekly types.
type PayPeriodScheduleShape = {
  type: string;
  anchorDate?: string | null;
  transactionDayOffset?: number | null;
  semiMonthlyDay1?: number | null;
  semiMonthlyDay2?: number | null;
};

/** Snap a date BACK to the most-recent Saturday (day 6).
 *  If the date is already Saturday, returns it unchanged. */
function snapToSaturday(d: Date): Date {
  const dow = d.getDay(); // 0=Sun … 6=Sat
  const daysBack = dow === 6 ? 0 : dow + 1;
  const sat = new Date(d);
  sat.setDate(d.getDate() - daysBack);
  return sat;
}

function resolvePayPeriod(
  schedule: PayPeriodScheduleShape,
  payDate: string
): { periodStart: string; periodEnd: string } | null {
  const pay = new Date(payDate + "T12:00:00");
  if (isNaN(pay.getTime())) return null;
  // For weekly type the canonical offset is 4 (Wed payday, 4 days after Sat).
  // For all other types fall back to the stored value or legacy default 3.
  const defaultOffset = schedule.type === "weekly" ? 4 : 3;
  const offset = schedule.transactionDayOffset ?? defaultOffset;
  const fmt = (d: Date) => d.toISOString().split("T")[0];

  if (schedule.type === "weekly") {
    // Back-calculate tentative period end then snap to nearest past Saturday.
    // This makes the resolver robust even when payDate is not exactly on payday.
    const tentativeEnd = new Date(pay);
    tentativeEnd.setDate(pay.getDate() - offset);
    const end = snapToSaturday(tentativeEnd);
    const start = new Date(end);
    start.setDate(end.getDate() - 6); // always Sunday
    return { periodStart: fmt(start), periodEnd: fmt(end) };
  }

  if (schedule.type === "biweekly") {
    const end = new Date(pay);
    end.setDate(pay.getDate() - offset);
    const start = new Date(end);
    start.setDate(end.getDate() - 13);
    return { periodStart: fmt(start), periodEnd: fmt(end) };
  }

  if (schedule.type === "semimonthly") {
    const day1 = schedule.semiMonthlyDay1 ?? 1;
    const day2 = schedule.semiMonthlyDay2 ?? 15;
    // Determine which half of the month this payDate covers
    const end = new Date(pay);
    end.setDate(pay.getDate() - offset);
    if (end.getDate() < day2) {
      // First half: day1 → day2-1
      const start = new Date(end.getFullYear(), end.getMonth(), day1);
      const capEnd = new Date(end.getFullYear(), end.getMonth(), day2 - 1);
      return { periodStart: fmt(start), periodEnd: fmt(capEnd) };
    } else {
      // Second half: day2 → last day of month
      const start = new Date(end.getFullYear(), end.getMonth(), day2);
      const capEnd = new Date(end.getFullYear(), end.getMonth() + 1, 0);
      return { periodStart: fmt(start), periodEnd: fmt(capEnd) };
    }
  }

  if (schedule.type === "monthly") {
    const end = new Date(pay);
    end.setDate(pay.getDate() - offset);
    const start = new Date(end.getFullYear(), end.getMonth(), 1);
    const capEnd = new Date(end.getFullYear(), end.getMonth() + 1, 0);
    return { periodStart: fmt(start), periodEnd: fmt(capEnd) };
  }

  return null;
}

// Helper: periodsPerYear from schedule type
function periodsPerYearFromSchedule(type: string): number {
  if (type === "weekly") return 52;
  if (type === "semimonthly") return 24;
  if (type === "monthly") return 12;
  return 26; // biweekly default
}

// Narrow typed accessor for db.execute() results — replaces ad-hoc
// `(result.rows ?? (result as any))[0]` patterns in contractor lifecycle
// handlers with a single, typed extraction point.
type DbExecResult<T> = { rows?: T[] } | T[];
function firstRow<T>(r: DbExecResult<T>): T | undefined {
  if (Array.isArray(r)) return r[0];
  return r.rows?.[0];
}

