  app.get("/api/time-clock/punches", async (req, res) => {
    try {
      const { workerId, employeeNumber, pin } = req.query;
      if (!workerId || !employeeNumber || !pin) {
        return res.status(400).json({ message: "workerId, employeeNumber, and pin are required" });
      }
      const worker = await storage.getWorker(workerId as string);
      if (!worker || worker.employeeNumber !== employeeNumber || worker.pin !== pin) {
        return res.status(401).json({ message: "Invalid credentials" });
      }
      const allPunches = await storage.getTimePunches(worker.companyId);
      const workerPunches = allPunches
        .filter(p => p.workerId === workerId)
        .sort((a, b) => new Date(b.punchTime).getTime() - new Date(a.punchTime).getTime())
        .slice(0, 20);
      res.json(workerPunches);
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Failed to fetch punches" });
    }
  });

  app.post("/api/time-clock/punch", async (req, res) => {
    try {
      const { workerId, companyId, punchType, employeeNumber, pin } = req.body;
      if (!workerId || !companyId || !punchType) {
        return res.status(400).json({ message: "workerId, companyId, and punchType are required" });
      }
      const worker = await storage.getWorker(workerId);
      if (!worker) return res.status(404).json({ message: "Worker not found" });
      if (employeeNumber && pin) {
        if (worker.employeeNumber !== employeeNumber || worker.pin !== pin) {
          return res.status(401).json({ message: "Invalid credentials" });
        }
      } else if (!req.session.userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }
      if (worker.workerType === "contractor" && worker.contractorType === "invoice") {
        return res.status(400).json({ message: "Invoice-based contractors cannot clock in/out." });
      }
      // Load company timezone + enforcement settings in one query
      const companyMeta = await db.execute(sql`SELECT station_enforcement_enabled, timezone FROM companies WHERE id = ${worker.companyId}`);
      const companyTzRow = companyMeta.rows[0] as any;
      const punchCompanyTz = companyTzRow?.timezone || "America/New_York";

      let matchedStationId: string | undefined;
      if (punchType === "clock_in" && worker.companyId) {
        const enforcementEnabled = companyTzRow?.station_enforcement_enabled === true;
        if (enforcementEnabled) {
          const allStations = await storage.getStations(worker.companyId);
          const activeStations = allStations.filter(s => s.status === "active");
          if (activeStations.length > 0) {
            const clientIp = req.ip || req.socket.remoteAddress || "";
            const matched = activeStations.find(s => {
              if (!s.ipRestriction) return false;
              const restrictions = s.ipRestriction.split(",").map(r => r.trim());
              return restrictions.some(r => {
                if (r.includes("/")) {
                  const [subnet, bits] = r.split("/");
                  const mask = ~((1 << (32 - parseInt(bits))) - 1) >>> 0;
                  const ipToNum = (ip: string) => ip.split(".").reduce((acc, oct) => (acc << 8) + parseInt(oct), 0) >>> 0;
                  return (ipToNum(clientIp) & mask) === (ipToNum(subnet) & mask);
                }
                return clientIp === r;
              });
            });
            if (!matched) {
              return res.status(403).json({ message: `Clock-in denied. Your IP address (${clientIp}) does not match any authorized station. Contact your administrator.` });
            }
            matchedStationId = matched.id;
          }
        }
      }
      const now = new Date();
      const today = getLocalDateStr(now, punchCompanyTz); // company local date, not UTC
      // Check if worker has a schedule for today (for unscheduled punch detection)
      let isUnscheduled = false;
      let matchingSchedule: any = null;
      let scheduledStart: Date | undefined;
      let scheduledEnd: Date | undefined;
      let scheduledHours: string | undefined;
      if (punchType === "clock_in") {
        const todaySchedules = await storage.getSchedulesByDateRange(companyId, today, today);
        const workerSchedule = todaySchedules.find(s => s.workerId === workerId);
        if (!workerSchedule) {
          isUnscheduled = true;
        } else {
          matchingSchedule = workerSchedule;
          scheduledStart = localTimeToUTC(today, workerSchedule.startTime, punchCompanyTz);
          scheduledEnd   = localTimeToUTC(today, workerSchedule.endTime,   punchCompanyTz);
          const [sh, sm] = workerSchedule.startTime.split(":").map(Number);
          const [eh, em] = workerSchedule.endTime.split(":").map(Number);
          const hrs = ((eh * 60 + em) - (sh * 60 + sm)) / 60;
          scheduledHours = Math.max(0, hrs).toFixed(2);
          // Flag as unscheduled if clocking in more than 2 hours before or after scheduled start
          const diffMin = Math.abs((now.getTime() - scheduledStart.getTime()) / 60000);
          if (diffMin > 120) isUnscheduled = true;
        }
      }

      // ── Self-service late clock-in: require manager approval ──
      // Only applies when the employee is authenticating with employeeNumber+pin
      // (not when an admin/manager is manually punching someone in via session).
      const PUNCH_GRACE_MINUTES = 10;
      const isSelfService = !!(req.body.employeeNumber && req.body.pin);
      if (punchType === "clock_in" && isSelfService && !isUnscheduled && scheduledStart) {
        const lateMs = now.getTime() - scheduledStart.getTime();
        const lateMin = Math.round(lateMs / 60000);
        if (lateMin > PUNCH_GRACE_MINUTES) {
          // Create a pending clock_in_request so managers can approve from the Attendance tab
          await db.execute(sql`
            INSERT INTO clock_in_requests
              (worker_id, company_id, request_type, minutes_diff, schedule_id, scheduled_start, scheduled_end)
            VALUES
              (${workerId}, ${companyId}, 'late_clockin', ${lateMin},
               ${matchingSchedule?.id ?? null},
               ${scheduledStart ? scheduledStart.toISOString() : null},
               ${scheduledEnd ? scheduledEnd.toISOString() : null})
          `);
          // Notify managers asynchronously
          (async () => {
            try {
              const { sendShiftMarketplaceEmail, sendShiftMarketplaceSms } = await import("./notifications.js");
              const allUsers = await storage.getUsers();
              const workerObj = await storage.getWorker(workerId);
              const workerName = workerObj ? `${workerObj.firstName} ${workerObj.lastName}` : workerId;
              const managers = allUsers.filter(u => (u.role === "admin" || u.role === "manager") && u.isActive && (!u.companyId || u.companyId === companyId));
              const appUrl = getAppBaseUrl(req);
              const subject = `Clock-In Approval Required — ${workerName}`;
              const bodyText = `${workerName} is ${lateMin} minutes late and needs manager approval to clock in.\n\nApprove at ${appUrl}/app/attendance?tab=clock-in-approvals`;
              for (const mgr of managers) {
                const mgrWorker = mgr.workerId ? await storage.getWorker(mgr.workerId) : null;
                const mgrEmail = mgrWorker?.workEmail || mgrWorker?.homeEmail || mgrWorker?.email || null;
                const mgrPhone = mgrWorker?.mobilePhone || mgrWorker?.homePhone || null;
                const mgrName = mgrWorker ? `${mgrWorker.firstName} ${mgrWorker.lastName}` : mgr.username;
                await Promise.all([
                  sendShiftMarketplaceEmail({ recipientName: mgrName, email: mgrEmail, subject, bodyText }),
                  sendShiftMarketplaceSms({ recipientName: mgrName, phone: mgrPhone, subject, bodyText: `PayLink: ${workerName} is ${lateMin} min late and needs clock-in approval. ${appUrl}/app/attendance?tab=clock-in-approvals` }),
                ]);
              }
            } catch (e) { console.warn("Late punch notification failed:", e); }
          })();
          return res.status(409).json({ message: `You are ${lateMin} minutes late. Your manager has been notified and must approve your clock-in.` });
        }
      }

      // ── Self-service early clock-in: require manager approval ──
      if (punchType === "clock_in" && isSelfService && !isUnscheduled && scheduledStart) {
        const earlyMs = scheduledStart.getTime() - now.getTime();
        const earlyMin = Math.round(earlyMs / 60000);
        if (earlyMin > PUNCH_GRACE_MINUTES) {
          await db.execute(sql`
            INSERT INTO clock_in_requests
              (worker_id, company_id, request_type, minutes_diff, schedule_id, scheduled_start, scheduled_end)
            VALUES
              (${workerId}, ${companyId}, 'early_clockin', ${-earlyMin},
               ${matchingSchedule?.id ?? null},
               ${scheduledStart ? scheduledStart.toISOString() : null},
               ${scheduledEnd ? scheduledEnd.toISOString() : null})
          `);
          return res.status(409).json({ message: `You are ${earlyMin} minutes early. Manager approval is required to clock in before your scheduled start time.` });
        }
      }

      const punchApprovalStatus = isUnscheduled ? "pending" : "approved";
      const punch = await storage.createTimePunch({
        workerId, companyId, punchType, punchTime: new Date(),
        approvalStatus: punchApprovalStatus,
        scheduleId: matchingSchedule?.id || undefined,
        stationId: matchedStationId ?? null,
      });

      if (punchType === "clock_in") {
        const allEntries = await storage.getTimeEntries();
        const staleOpenEntries = allEntries.filter(
          (e) => e.workerId === workerId && e.clockIn && !e.clockOut && e.date !== today
        );
        for (const stale of staleOpenEntries) {
          const staleClockIn = new Date(stale.clockIn!);
          const elapsed = (Date.now() - staleClockIn.getTime()) / (1000 * 60 * 60);
          const cappedHours = Math.min(elapsed, 8).toFixed(2);
          const staleClockOut = new Date(staleClockIn.getTime() + parseFloat(cappedHours) * 60 * 60 * 1000);
          await storage.updateTimeEntry(stale.id, {
            clockOut: staleClockOut, totalHours: cappedHours, overtimeHours: "0.00", doubleTimeHours: "0.00",
          });
        }
        const lateMinutes = scheduledStart ? Math.max(0, Math.round((now.getTime() - scheduledStart.getTime()) / 60000)) : 0;
        await storage.createTimeEntry({
          workerId, companyId, date: today, clockIn: now, status: "pending",
          scheduleId: matchingSchedule?.id || undefined,
          scheduledStart: scheduledStart || undefined,
          scheduledEnd: scheduledEnd || undefined,
          scheduledHours: scheduledHours || undefined,
          lateMinutes, isUnscheduled,
          source: "punches",
          note: isUnscheduled ? "No matching schedule — unscheduled shift" : undefined,
        });
      } else if (punchType === "clock_out") {
        const entries = await storage.getTimeEntries();
        // Sort by clockIn descending so we always close the MOST RECENT open entry,
        // not a stale one from an earlier failed or pending clock-in attempt.
        const openEntry = entries
          .filter(e => e.workerId === workerId && e.clockIn && !e.clockOut)
          .sort((a, b) => new Date(b.clockIn!).getTime() - new Date(a.clockIn!).getTime())[0];
        if (openEntry) {
          const clockIn = new Date(openEntry.clockIn!);
          const clockOut = new Date();
          const totalMs = clockOut.getTime() - clockIn.getTime();
          const breakMs = (openEntry.breakMinutes || 0) * 60 * 1000;
          const workedHours = Math.max(0, (totalMs - breakMs) / (1000 * 60 * 60));
          const otHours = Math.max(0, workedHours - 8);
          const dtHours = Math.max(0, workedHours - 12);
          await storage.updateTimeEntry(openEntry.id, {
            clockOut, totalHours: workedHours.toFixed(2),
            overtimeHours: otHours.toFixed(2), doubleTimeHours: dtHours.toFixed(2),
          });
        }
      }
      res.status(201).json({
        ...punch,
        warning: isUnscheduled ? "No schedule found for today — this punch requires manager approval." : undefined,
      });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Punch failed" });
    }
  });

  // Sign in without punch — auth + session only
  // Supports: (1) employee number + PIN, (2) username + password for admin/manager
  app.post("/api/time-clock/sign-in", async (req, res) => {
    try {
      const { employeeNumber, pin } = req.body;
      if (!employeeNumber || !pin) return res.status(400).json({ message: "Employee number and PIN are required" });

      // ── Path 1: Employee number + PIN ────────────────────────────────────
      const worker = await storage.getWorkerByEmployeeNumberAndPin(employeeNumber, pin);
      if (worker) {
        if (!worker.isActive) return res.status(403).json({ message: "This employee account is inactive" });
        const allUsers = await storage.getUsers();
        let user = allUsers.find(u => u.workerId === worker.id);
        if (!user) {
          const hashedPassword = await bcrypt.hash(pin, 10);
          user = await storage.createUser({ username: employeeNumber, password: hashedPassword, role: "employee", companyId: worker.companyId, workerId: worker.id, isActive: true });
        }
        if (user.isActive === false) return res.status(403).json({ message: "Account is disabled. Contact your administrator." });
        req.session.userId = user.id;
        req.session.username = user.username;
        req.session.save((err) => {
          if (err) return res.status(500).json({ message: "Authentication failed" });
          res.json({ id: user!.id, username: user!.username, role: user!.role, workerId: user!.workerId, companyId: user!.companyId, worker: { id: worker.id, firstName: worker.firstName, lastName: worker.lastName } });
        });
        return;
      }

      // ── Path 2: Username + password fallback for admin/manager users ──────
      const allUsers = await storage.getUsers();
      const matchUser = allUsers.find(u => u.username === employeeNumber && u.isActive !== false);
      if (matchUser) {
        const passwordMatch = await bcrypt.compare(pin, matchUser.password);
        if (passwordMatch) {
          req.session.userId = matchUser.id;
          req.session.username = matchUser.username;
          const workerRecord = matchUser.workerId ? await storage.getWorker(matchUser.workerId) : null;
          req.session.save((err) => {
            if (err) return res.status(500).json({ message: "Authentication failed" });
            res.json({
              id: matchUser.id,
              username: matchUser.username,
              role: matchUser.role,
              workerId: matchUser.workerId,
              companyId: matchUser.companyId,
              worker: workerRecord ? { id: workerRecord.id, firstName: workerRecord.firstName, lastName: workerRecord.lastName } : null,
            });
          });
          return;
        }
      }

      return res.status(401).json({ message: "Invalid employee number or PIN" });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Sign in failed" });
    }
  });

  // Clock in + session — auth + clock_in punch + session creation
  app.post("/api/time-clock/clock-in-session", async (req, res) => {
    try {
      const { employeeNumber, pin, wageGroupId } = req.body;
      if (!employeeNumber || !pin) return res.status(400).json({ message: "Employee number and PIN are required" });
      const worker = await storage.getWorkerByEmployeeNumberAndPin(employeeNumber, pin);
      if (!worker) return res.status(401).json({ message: "Invalid employee number or PIN. If you have not set up a PIN, ask your administrator." });
      if (!worker.isActive) return res.status(403).json({ message: "This employee account is inactive" });
      if (worker.workerType === "contractor" && worker.contractorType === "invoice") {
        return res.status(400).json({ message: "Invoice-based contractors cannot clock in." });
      }

      // ── Create / restore session so the employee lands on their dashboard ──
      const clockInUsers = await storage.getUsers();
      let clockInUser = clockInUsers.find(u => u.workerId === worker.id);
      if (!clockInUser) {
        const hashedPassword = await bcrypt.hash(pin, 10);
        clockInUser = await storage.createUser({ username: employeeNumber, password: hashedPassword, role: "employee", companyId: worker.companyId, workerId: worker.id, isActive: true });
      }
      if (clockInUser.isActive === false) return res.status(403).json({ message: "Account is disabled. Contact your administrator." });
      await new Promise<void>((resolve, reject) => {
        req.session.userId = clockInUser!.id;
        req.session.username = clockInUser!.username;
        req.session.save((err) => { if (err) reject(err); else resolve(); });
      });

      // Duplicate clock-in prevention
      const allPunches = await storage.getTimePunches(worker.companyId);
      const workerPunches = allPunches.filter(p => p.workerId === worker.id).sort((a, b) => new Date(b.punchTime).getTime() - new Date(a.punchTime).getTime());
      const lastPunch = workerPunches[0];
      if (lastPunch && (lastPunch.punchType === "clock_in" || lastPunch.punchType === "break_end")) {
        return res.status(409).json({ message: "You are already clocked in. Please clock out first." });
      }

      // ── Schedule check: 10-minute grace period ──
      // Load company timezone so late-night punches get the correct LOCAL date.
      // Without this, an 11 PM Eastern punch stores as the next day in UTC.
      const companyObj = worker.companyId ? await storage.getCompany(worker.companyId) : null;
      const companyTz = companyObj?.timezone || "America/New_York";
      const now = new Date();
      const today = getLocalDateStr(now, companyTz); // correct local date in company TZ
      // Use per-company configurable grace period (default 10 min if not set)
      const GRACE_MINUTES = (companyObj as any)?.clockInGraceMinutes ?? 10;
      let requestType: string | null = null;
      let minutesDiff = 0;
      let matchingSchedule: any = null;
      let scheduledStart: Date | undefined;
      let scheduledEnd: Date | undefined;
      // effectiveCompanyId is the company this shift belongs to — may differ from
      // worker.companyId when a worker is cross-scheduled at another company.
      let effectiveCompanyId: string = worker.companyId || "";

      if (worker.companyId) {
        const todaySchedules = await storage.getSchedulesByDateRange(worker.companyId, today, today);
        let workerSchedule = todaySchedules.find(s => s.workerId === worker.id);

        // If no schedule found in the worker's home company, look across all companies.
        // This handles cross-company shifts (e.g. an Adiken worker scheduled at Lucifer Cruz).
        if (!workerSchedule) {
          const { schedules: schedulesTable } = await import("../shared/schema.js");
          const crossSchedules = await db.select().from(schedulesTable)
            .where(and(eq(schedulesTable.workerId, worker.id), eq(schedulesTable.date, today)))
            .limit(1);
          if (crossSchedules[0]) {
            workerSchedule = crossSchedules[0] as any;
            effectiveCompanyId = crossSchedules[0].companyId;
            console.log(`[CLOCK-IN] Worker ${worker.firstName} ${worker.lastName} has cross-company schedule at companyId=${effectiveCompanyId} (home=${worker.companyId})`);
          }
        }

        if (workerSchedule) {
          matchingSchedule = workerSchedule;
          // Convert "HH:MM" schedule times to UTC using the company timezone so
          // the diff calculation is correct regardless of server OS timezone.
          scheduledStart = localTimeToUTC(today, workerSchedule.startTime, companyTz);
          scheduledEnd   = localTimeToUTC(today, workerSchedule.endTime,   companyTz);
          const diffMs = now.getTime() - scheduledStart.getTime();
          minutesDiff = Math.round(diffMs / 60000);
          if (minutesDiff < -GRACE_MINUTES) {
            requestType = "early_clockin";
          } else if (minutesDiff > GRACE_MINUTES) {
            requestType = "late_clockin";
          }
          // Within grace period: no approval needed (requestType stays null)
        } else {
          // No schedule for today → out-of-schedule (unscheduled) punch requires approval
          requestType = "unscheduled";
          minutesDiff = 0;
        }
      }

      // All schedule violations (early, late, unscheduled) require manager approval
      if (requestType) {
        const requestRow = await db.execute(sql`
          INSERT INTO clock_in_requests
            (worker_id, company_id, request_type, minutes_diff, schedule_id, scheduled_start, scheduled_end)
          VALUES
            (${worker.id}, ${effectiveCompanyId}, ${requestType}, ${minutesDiff},
             ${matchingSchedule?.id ?? null},
             ${scheduledStart ? scheduledStart.toISOString() : null},
             ${scheduledEnd ? scheduledEnd.toISOString() : null})
          RETURNING id
        `);
        const requestId = (requestRow.rows[0] as any).id;

        // Notify managers asynchronously — in-app + email/SMS (when allowed by company policy)
        // Target managers of the EFFECTIVE company (the one the shift belongs to), not the worker's home company.
        (async () => {
          try {
            const { sendShiftMarketplaceEmail, sendShiftMarketplaceSms } = await import("./notifications.js");
            const allUsers = await storage.getUsers();
            const managers = allUsers.filter(u =>
              isManagerRole(u.role) &&
              u.isActive &&
              (u.companyId === effectiveCompanyId || (!u.companyId && isAdminRole(u.role)))
            );
            const workerName = `${worker.firstName} ${worker.lastName}`;
            const appUrl = getAppBaseUrl(req);
            const reasonLabel = requestType === "early_clockin"
              ? `Early clock-in (${Math.abs(minutesDiff)} min early)`
              : requestType === "late_clockin"
              ? `Late clock-in (${minutesDiff} min late)`
              : "Unscheduled clock-in";
            const subject = `Clock-In Approval Required — ${workerName}`;
            const bodyText = `${workerName} is requesting to clock in but is outside their scheduled time.\n\nReason: ${reasonLabel}\n${scheduledStart ? `Scheduled start: ${scheduledStart.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })}\n` : ""}Current time: ${now.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })}\n\nPlease log in to approve or deny this request:\n${appUrl}/app/attendance?tab=clock-in-approvals`;
            for (const mgr of managers) {
              // 1. In-app notification (always created, visible in notification bell/inbox)
              if (mgr.companyId === effectiveCompanyId) {
                await db.execute(sql`
                  INSERT INTO notifications (company_id, user_id, worker_id, type, title, message, action_url, is_read)
                  VALUES (
                    ${effectiveCompanyId},
                    ${mgr.id},
                    ${mgr.workerId ?? null},
                    'clock_in_approval',
                    ${subject},
                    ${`${workerName} needs clock-in approval: ${reasonLabel}`},
                    '/app/attendance?tab=clock-in-approvals',
                    false
                  )
                `).catch(e => console.warn("In-app notification insert failed:", e));
              }
              // 2. Email/SMS — gated on company's notifyMgrOnViolations policy (default true)
              if ((companyObj as any)?.notifyMgrOnViolations !== false) {
                const mgrWorker = mgr.workerId ? await storage.getWorker(mgr.workerId) : null;
                const mgrEmail = mgrWorker?.workEmail || mgrWorker?.homeEmail || mgrWorker?.email || null;
                const mgrPhone = mgrWorker?.mobilePhone || mgrWorker?.homePhone || null;
                const mgrName = mgrWorker ? `${mgrWorker.firstName} ${mgrWorker.lastName}` : mgr.username;
                await Promise.all([
                  sendShiftMarketplaceEmail({ recipientName: mgrName, email: mgrEmail, subject, bodyText }),
                  sendShiftMarketplaceSms({ recipientName: mgrName, phone: mgrPhone, subject, bodyText: `PayLink: ${workerName} needs clock-in approval (${reasonLabel}). Approve at ${appUrl}/app/attendance?tab=clock-in-approvals` }),
                ]);
              }
            }
          } catch (e) { console.warn("Clock-in approval notification failed:", e); }
        })();

        return res.status(202).json({
          status: "pending_approval",
          requestId,
          requestType,
          minutesDiff,
          worker: { id: worker.id, firstName: worker.firstName, lastName: worker.lastName },
          message: requestType === "early_clockin"
            ? `You are ${Math.abs(minutesDiff)} minutes early. Manager approval required.`
            : requestType === "late_clockin"
            ? `You are ${minutesDiff} minutes late. Manager approval required.`
            : "You are not scheduled today. Manager approval required.",
        });
      }

      // Within grace period — create punch and time entry directly.
      // Use effectiveCompanyId so cross-company scheduled workers get their hours
      // stamped against the company that owns the shift (not their home company).
      const punch = await storage.createTimePunch({ workerId: worker.id, companyId: effectiveCompanyId, punchType: "clock_in", punchTime: new Date(), approvalStatus: "approved", stationId: null, scheduleId: matchingSchedule?.id || null });
      // Close any stale open entries from previous days
      const allEntries = await storage.getTimeEntries();
      const staleOpenEntries = allEntries.filter(e => e.workerId === worker.id && e.clockIn && !e.clockOut && e.date !== today);
      for (const stale of staleOpenEntries) {
        const staleClockIn = new Date(stale.clockIn!);
        const elapsed = (Date.now() - staleClockIn.getTime()) / (1000 * 60 * 60);
        const cappedHours = Math.min(elapsed, 8).toFixed(2);
        const staleClockOut = new Date(staleClockIn.getTime() + parseFloat(cappedHours) * 60 * 60 * 1000);
        await storage.updateTimeEntry(stale.id, { clockOut: staleClockOut, totalHours: cappedHours, overtimeHours: "0.00", doubleTimeHours: "0.00" });
      }
      const lateMinutes = scheduledStart ? Math.max(0, Math.round((now.getTime() - scheduledStart.getTime()) / 60000)) : 0;
      await storage.createTimeEntry({
        workerId: worker.id, companyId: effectiveCompanyId, date: today, clockIn: now, status: "pending", source: "punches",
        scheduleId: matchingSchedule?.id || undefined,
        scheduledStart: scheduledStart || undefined,
        scheduledEnd: scheduledEnd || undefined,
        lateMinutes,
      });

      res.status(201).json({ punch, worker: { id: worker.id, firstName: worker.firstName, lastName: worker.lastName }, sessionCreated: true });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Clock in failed" });
    }
  });

  // Clock out — auth + clock_out punch (no session needed after clock out)
  // Returns position flags for the worker's active session — used by the clock-out UI
  // to decide which prompt to show (commission entry, tips entry, or neither).
  app.post("/api/time-clock/session-info", async (req, res) => {
    try {
      const { employeeNumber, pin } = req.body;
      if (!employeeNumber || !pin) return res.status(400).json({ message: "Employee number and PIN are required" });
      const worker = await storage.getWorkerByEmployeeNumberAndPin(employeeNumber, pin);
      if (!worker) return res.status(401).json({ message: "Invalid employee number or PIN." });
      if (!worker.isActive) return res.status(403).json({ message: "This employee account is inactive" });

      // Find the worker's open time entry to get their schedule's positionId
      const allEntries = await storage.getTimeEntries();
      const openEntry = allEntries
        .filter(e => e.workerId === worker.id && e.clockIn && !e.clockOut)
        .sort((a, b) => new Date(b.clockIn!).getTime() - new Date(a.clockIn!).getTime())[0];

      let positionPayType: string | null = null;
      let positionIsTipped = false;
      let positionTitle: string | null = null;

      if (openEntry?.scheduleId) {
        const { schedules: schedulesTable } = await import("../shared/schema.js");
        const [schedule] = await db.select().from(schedulesTable).where(eq(schedulesTable.id, openEntry.scheduleId));
        if (schedule?.positionId) {
          const allPositions = await storage.getPositions(worker.companyId);
          const pos = allPositions.find((p: any) => p.id === schedule.positionId);
          if (pos) {
            positionPayType = (pos as any).payType || null;
            positionIsTipped = (pos as any).isTipped === true;
            positionTitle = (pos as any).title || null;
          }
        }
      } else if (openEntry?.positionId) {
        const allPositions = await storage.getPositions(worker.companyId);
        const pos = allPositions.find((p: any) => p.id === openEntry.positionId);
        if (pos) {
          positionPayType = (pos as any).payType || null;
          positionIsTipped = (pos as any).isTipped === true;
          positionTitle = (pos as any).title || null;
        }
      }

      return res.json({
        worker: { id: worker.id, firstName: worker.firstName, lastName: worker.lastName },
        positionPayType,
        positionIsTipped,
        positionTitle,
        hasClockedIn: !!openEntry,
      });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Failed to fetch session info" });
    }
  });

  app.post("/api/time-clock/clock-out-session", async (req, res) => {
    try {
      const { employeeNumber, pin, tipsAmount, commissionAmount } = req.body;
      if (!employeeNumber || !pin) return res.status(400).json({ message: "Employee number and PIN are required" });
      const worker = await storage.getWorkerByEmployeeNumberAndPin(employeeNumber, pin);
      if (!worker) return res.status(401).json({ message: "Invalid employee number or PIN. If you have not set up a PIN, ask your administrator." });
      if (!worker.isActive) return res.status(403).json({ message: "This employee account is inactive" });
      // Must have an open shift
      const allPunches = await storage.getTimePunches(worker.companyId);
      const workerPunches = allPunches.filter(p => p.workerId === worker.id).sort((a, b) => new Date(b.punchTime).getTime() - new Date(a.punchTime).getTime());
      const lastPunch = workerPunches[0];
      if (!lastPunch || lastPunch.punchType === "clock_out") {
        return res.status(409).json({ message: "You are not currently clocked in." });
      }
      // Create punch
      const punch = await storage.createTimePunch({ workerId: worker.id, companyId: worker.companyId, punchType: "clock_out", punchTime: new Date(), approvalStatus: "approved", stationId: null });
      // Close open time entry — sort by clockIn DESC to always close the most recent open entry
      const now = new Date();
      const allEntries = await storage.getTimeEntries();
      const openEntry = allEntries
        .filter(e => e.workerId === worker.id && e.clockIn && !e.clockOut)
        .sort((a, b) => new Date(b.clockIn!).getTime() - new Date(a.clockIn!).getTime())[0];
      if (openEntry) {
        const clockIn = new Date(openEntry.clockIn!);
        const clockOut = now;
        const totalMs = clockOut.getTime() - clockIn.getTime();
        const breakMs = (openEntry.breakMinutes || 0) * 60 * 1000;
        const workedHours = Math.max(0, (totalMs - breakMs) / (1000 * 60 * 60));
        const otHours = Math.max(0, workedHours - 8);
        const dtHours = Math.max(0, workedHours - 12);
        const parsedTips = tipsAmount ? parseFloat(tipsAmount) : 0;
        await storage.updateTimeEntry(openEntry.id, {
          clockOut, totalHours: workedHours.toFixed(2),
          overtimeHours: otHours.toFixed(2), doubleTimeHours: dtHours.toFixed(2),
          ...(parsedTips > 0 ? { tipsAmount: parsedTips.toFixed(2) } : {}),
        });

        const coObj = worker.companyId ? await storage.getCompany(worker.companyId) : null;
        const coTz = coObj?.timezone || "America/New_York";
        const todayStr = getLocalDateStr(now, coTz);

        // Auto-create a pending commission record for self-reported tips
        if (parsedTips > 0) {
          try {
            const existingTypes = await storage.getEarningTypes(worker.companyId);
            let tipsType = existingTypes.find(t => t.code === "tips");
            if (!tipsType) {
              tipsType = await storage.createEarningType({
                companyId: worker.companyId,
                code: "tips",
                label: "Tips",
                isTaxable: true,
              });
            }
            await storage.createCommission({
              companyId: worker.companyId,
              workerId: worker.id,
              amount: parsedTips.toFixed(2),
              description: `Self-reported tips from clock-out on ${todayStr}`,
              sourceType: "tips",
              sourceId: openEntry.id,
              earnedDate: todayStr,
              status: "pending",
              payrollRunId: null,
            });
          } catch (tipErr) {
            console.warn("Tips commission creation failed (non-blocking):", tipErr);
          }
        }

        // Auto-create a pending commission record for self-reported commission sales
        const parsedCommission = commissionAmount ? parseFloat(commissionAmount) : 0;
        if (parsedCommission > 0) {
          try {
            const existingTypes = await storage.getEarningTypes(worker.companyId);
            let commType = existingTypes.find(t => t.code === "sales_commission");
            if (!commType) {
              commType = await storage.createEarningType({
                companyId: worker.companyId,
                code: "sales_commission",
                label: "Sales Commission",
                isTaxable: true,
              });
            }
            await storage.createCommission({
              companyId: worker.companyId,
              workerId: worker.id,
              amount: parsedCommission.toFixed(2),
              description: `Self-reported commission from clock-out on ${todayStr}`,
              sourceType: "commission",
              sourceId: openEntry.id,
              earnedDate: todayStr,
              status: "pending",
              payrollRunId: null,
            });
          } catch (commErr) {
            console.warn("Commission creation failed (non-blocking):", commErr);
          }
        }
      }

      // ── Late clock-out notification (notify managers but don't block) ──
      if (worker.companyId) {
        // Use company timezone so late-night clock-outs resolve to the correct local date
        const coObj = worker.companyId ? await storage.getCompany(worker.companyId) : null;
        const coTz = coObj?.timezone || "America/New_York";
        const today = getLocalDateStr(now, coTz);
        const todaySchedules = await storage.getSchedulesByDateRange(worker.companyId, today, today);
        const workerSchedule = todaySchedules.find(s => s.workerId === worker.id);
        if (workerSchedule) {
          const scheduledEnd = localTimeToUTC(today, workerSchedule.endTime, coTz);
          const lateClockOutMin = Math.round((now.getTime() - scheduledEnd.getTime()) / 60000);
          if (lateClockOutMin > 10) {
            (async () => {
              try {
                const { sendShiftMarketplaceEmail, sendShiftMarketplaceSms } = await import("./notifications.js");
                const allUsers = await storage.getUsers();
                const managers = allUsers.filter(u =>
                  (u.role === "admin" || u.role === "manager") && u.isActive &&
                  (!u.companyId || u.companyId === worker.companyId)
                );
                const workerName = `${worker.firstName} ${worker.lastName}`;
                const appUrl = getAppBaseUrl(req);
                const subject = `Late Clock-Out — ${workerName}`;
                const bodyText = `${workerName} clocked out ${lateClockOutMin} minutes after their scheduled end time.\n\nScheduled end: ${workerSchedule.endTime}\nActual clock-out: ${now.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })}\n\nView timesheet: ${appUrl}/app/attendance`;
                for (const mgr of managers) {
                  const mgrWorker = mgr.workerId ? await storage.getWorker(mgr.workerId) : null;
                  const mgrEmail = mgrWorker?.workEmail || mgrWorker?.homeEmail || mgrWorker?.email || null;
                  const mgrPhone = mgrWorker?.mobilePhone || mgrWorker?.homePhone || null;
                  const mgrName = mgrWorker ? `${mgrWorker.firstName} ${mgrWorker.lastName}` : mgr.username;
                  await Promise.all([
                    sendShiftMarketplaceEmail({ recipientName: mgrName, email: mgrEmail, subject, bodyText }),
                    sendShiftMarketplaceSms({ recipientName: mgrName, phone: mgrPhone, subject, bodyText: `PayLink: ${workerName} clocked out ${lateClockOutMin} min late. View timesheet: ${appUrl}/app/attendance` }),
                  ]);
                }
              } catch (e) { console.warn("Late clock-out notification failed:", e); }
            })();
          }
        }
      }

      res.status(201).json({ punch, worker: { id: worker.id, firstName: worker.firstName, lastName: worker.lastName } });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Clock out failed" });
    }
  });

  // Break start — auth + break_start punch (starting a break)
  app.post("/api/time-clock/break-start", async (req, res) => {
    try {
      const { employeeNumber, pin } = req.body;
      if (!employeeNumber || !pin) return res.status(400).json({ message: "Employee number and PIN are required" });
      const worker = await storage.getWorkerByEmployeeNumberAndPin(employeeNumber, pin);
      if (!worker) return res.status(401).json({ message: "Invalid employee number or PIN. If you have not set up a PIN, ask your administrator." });
      if (!worker.isActive) return res.status(403).json({ message: "This employee account is inactive" });
      const allPunches = await storage.getTimePunches(worker.companyId);
      const workerPunches = allPunches.filter(p => p.workerId === worker.id).sort((a, b) => new Date(b.punchTime).getTime() - new Date(a.punchTime).getTime());
      const lastPunch = workerPunches[0];
      if (!lastPunch || lastPunch.punchType === "clock_out" || lastPunch.punchType === "break_start") {
        return res.status(409).json({ message: lastPunch?.punchType === "break_start" ? "You are already on a break." : "You are not currently clocked in." });
      }
      const punch = await storage.createTimePunch({ workerId: worker.id, companyId: worker.companyId, punchType: "break_start", punchTime: new Date(), approvalStatus: "approved", stationId: null });
      res.status(201).json({ punch, worker: { id: worker.id, firstName: worker.firstName, lastName: worker.lastName } });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Break start failed" });
    }
  });

  // Break end — auth + break_end punch (returning from break)
  app.post("/api/time-clock/break-end", async (req, res) => {
    try {
      const { employeeNumber, pin } = req.body;
      if (!employeeNumber || !pin) return res.status(400).json({ message: "Employee number and PIN are required" });
      const worker = await storage.getWorkerByEmployeeNumberAndPin(employeeNumber, pin);
      if (!worker) return res.status(401).json({ message: "Invalid employee number or PIN. If you have not set up a PIN, ask your administrator." });
      if (!worker.isActive) return res.status(403).json({ message: "This employee account is inactive" });
      const allPunches = await storage.getTimePunches(worker.companyId);
      const workerPunches = allPunches.filter(p => p.workerId === worker.id).sort((a, b) => new Date(b.punchTime).getTime() - new Date(a.punchTime).getTime());
      const lastPunch = workerPunches[0];
      if (!lastPunch || lastPunch.punchType !== "break_start") {
        return res.status(409).json({ message: "You are not currently on a break." });
      }
      const punch = await storage.createTimePunch({ workerId: worker.id, companyId: worker.companyId, punchType: "break_end", punchTime: new Date(), approvalStatus: "approved", stationId: null });
      // Update open time entry break minutes
      const allEntries = await storage.getTimeEntries();
      const openEntry = allEntries.find(e => e.workerId === worker.id && e.clockIn && !e.clockOut);
      if (openEntry) {
        const breakStart = new Date(lastPunch.punchTime);
        const breakMinutesThisBreak = (Date.now() - breakStart.getTime()) / (1000 * 60);
        const existingBreakMinutes = openEntry.breakMinutes || 0;
        await storage.updateTimeEntry(openEntry.id, { breakMinutes: (existingBreakMinutes + breakMinutesThisBreak).toFixed(0) as any });
      }
      res.status(201).json({ punch, worker: { id: worker.id, firstName: worker.firstName, lastName: worker.lastName } });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Break end failed" });
    }
  });

  // ── Payroll Pre-Flight Review (Structured Rule Engine + optional AI summary) ──
  app.post("/api/payroll-runs/:id/ai-review", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });

      const workers = await storage.getWorkers(run.companyId);
      const entries = await storage.getTimeEntriesByDateRange(run.companyId, run.periodStart, run.periodEnd);
      const existingItems = await storage.getPayrollItems(run.id);
      const allAmendments = await storage.getPayStubAmendments(run.companyId);

      // ── Deterministic rule engine ──────────────────────────────────────────
      type PreflightFlag = {
        severity: "blocking" | "warning" | "info";
        category: "compensation" | "time" | "tax" | "earnings" | "compliance";
        title: string;
        detail: string;
        worker?: string;
        fixPath?: string;
        fixLabel?: string;
      };

      const flags: PreflightFlag[] = [];
      const workerMap = Object.fromEntries(workers.map(w => [w.id, w]));

      // Build time entry hours per worker
      const hoursPerWorker: Record<string, { reg: number; ot: number; dt: number }> = {};
      for (const e of entries) {
        if (!hoursPerWorker[e.workerId]) hoursPerWorker[e.workerId] = { reg: 0, ot: 0, dt: 0 };
        hoursPerWorker[e.workerId].reg += parseFloat(e.regularHours?.toString() || "0");
        hoursPerWorker[e.workerId].ot += parseFloat(e.overtimeHours?.toString() || "0");
        hoursPerWorker[e.workerId].dt += parseFloat(e.doubleTimeHours?.toString() || "0");
      }

      // Amendments applied to this run (by workerId)
      const amendmentsByWorker: Record<string, typeof allAmendments[0][]> = {};
      for (const a of allAmendments) {
        if (a.appliedPayrollRunId === run.id) {
          if (!amendmentsByWorker[a.workerId]) amendmentsByWorker[a.workerId] = [];
          amendmentsByWorker[a.workerId].push(a);
        }
      }

      // ── Per-item rules (runs on processed items; on draft, runs on active workers) ──
      const itemsToCheck = existingItems.length > 0 ? existingItems : [];

      for (const item of itemsToCheck) {
        const worker = workerMap[item.workerId];
        // Skip inactive workers — they may appear in processed items if terminated mid-period
        if (worker && worker.isActive === false) continue;
        const workerName = worker ? `${worker.firstName} ${worker.lastName}` : `Worker ${item.workerId.slice(0, 8)}`;
        const isContractor = worker?.workerType === "contractor" || worker?.employmentType === "contractor";
        const payType = (item.payType || (worker as any)?.payType || "hourly") as string;
        const isSalary = payType === "salary";
        const payRate = parseFloat(item.payRate?.toString() || "0");
        const grossPay = parseFloat(item.grossPay?.toString() || "0");
        const regularHours = parseFloat(item.regularHours?.toString() || "0");
        const otHours = parseFloat(item.overtimeHours?.toString() || "0");
        const totalHours = regularHours + otHours;
        const deductions = parseFloat(item.deductions?.toString() || "0");
        const workerAmendments = amendmentsByWorker[item.workerId] || [];
        const hasAmendments = workerAmendments.length > 0;
        const timeEntryHours = hoursPerWorker[item.workerId];
        const hasTimeEntries = timeEntryHours && (timeEntryHours.reg + timeEntryHours.ot + timeEntryHours.dt) > 0;

        // ── 1. Compensation: pay rate check ─────────────────────────────────
        if (isSalary) {
          if (payRate === 0) {
            flags.push({
              severity: "blocking",
              category: "compensation",
              title: `${workerName} — Zero annual salary`,
              detail: `This salaried employee has a $0.00 annual pay rate. Their gross pay of $${grossPay.toFixed(2)} could not be correctly calculated. Update their compensation record before processing.`,
              worker: workerName,
              fixPath: "/app/employees",
              fixLabel: "Open Employee Profile",
            });
          }
        } else {
          if (payRate === 0 && !isContractor) {
            flags.push({
              severity: "blocking",
              category: "compensation",
              title: `${workerName} — Zero hourly pay rate`,
              detail: `This hourly employee has a $0.00/hr pay rate. Their gross pay of $${grossPay.toFixed(2)} is likely incorrect. Update their hourly rate before finalizing payroll.`,
              worker: workerName,
              fixPath: "/app/employees",
              fixLabel: "Open Employee Profile",
            });
          }
        }

        // ── 2. Time entries check ────────────────────────────────────────────
        if (!isSalary && !isContractor) {
          if (totalHours === 0 && grossPay > 0) {
            if (hasAmendments) {
              // Gross pay from adjustments — expected
              const adjDesc = workerAmendments.map(a => a.description || a.amendmentType || "adjustment").join(", ");
              flags.push({
                severity: "info",
                category: "earnings",
                title: `${workerName} — Gross pay from manual adjustments`,
                detail: `No time entries found, but gross pay of $${grossPay.toFixed(2)} is sourced from pay adjustments: ${adjDesc}. Verify this is intentional.`,
                worker: workerName,
                fixPath: "/app/payroll?tab=amendments",
                fixLabel: "Review Adjustments",
              });
            } else {
              flags.push({
                severity: "warning",
                category: "time",
                title: `${workerName} — Gross pay with no recorded hours`,
                detail: `This hourly employee has $${grossPay.toFixed(2)} gross pay but no time entries for this period. Verify whether hours were recorded, a manual adjustment exists, or this is an error.`,
                worker: workerName,
                fixPath: "/app/attendance?tab=timesheet",
                fixLabel: "Open Time Clock",
              });
            }
          } else if (totalHours === 0 && grossPay === 0) {
            // No hours, no pay — skip (not included in payroll)
          } else if (totalHours > 60) {
            flags.push({
              severity: "warning",
              category: "compliance",
              title: `${workerName} — High hours this period`,
              detail: `${workerName} has ${totalHours.toFixed(1)} total hours this pay period, which exceeds 60 hours/week. Verify overtime calculation and ensure compliance with labor laws.`,
              worker: workerName,
              fixPath: "/app/attendance?tab=timesheet",
              fixLabel: "Review Time Entries",
            });
          }
        } else if (isSalary && grossPay === 0) {
          flags.push({
            severity: "blocking",
            category: "earnings",
            title: `${workerName} — Salary worker with $0 gross pay`,
            detail: `This salaried employee shows $0.00 gross pay. Check their annual salary rate and pay period schedule to ensure correct proration.`,
            worker: workerName,
            fixPath: "/app/settings",
            fixLabel: "Open Payroll Settings",
          });
        }

        // ── 3. Tax / deductions check ────────────────────────────────────────
        if (!isContractor && worker) {
          const missingItems: string[] = [];
          if (!worker.ssn) missingItems.push("Social Security Number (SSN) — required for W-2 filing");
          if (deductions === 0 && grossPay > 100) {
            missingItems.push("Tax deductions are $0 for a non-exempt employee with positive gross pay — verify withholding elections");
          }
          if (missingItems.length > 0) {
            flags.push({
              severity: missingItems.some(m => m.includes("SSN")) ? "warning" : "warning",
              category: "tax",
              title: `${workerName} — Incomplete tax setup`,
              detail: `Missing: ${missingItems.join("; ")}.`,
              worker: workerName,
              fixPath: "/app/payroll?tab=tax-wizard",
              fixLabel: "Open Tax Setup",
            });
          }
        }

        // ── 4. Earnings source summary (info) for salaried workers ──────────
        if (isSalary && grossPay > 0) {
          const sources: string[] = ["Salary allocation"];
          if (hasAmendments) sources.push(`${workerAmendments.length} manual adjustment(s)`);
          flags.push({
            severity: "info",
            category: "earnings",
            title: `${workerName} — Salary earnings breakdown`,
            detail: `Gross pay of $${grossPay.toFixed(2)} sources: ${sources.join(", ")}. No time entries required for salaried employees.`,
            worker: workerName,
          });
        }
      }

      // ── 5. Draft-mode: check active workers with $0 rate not in any item ──
      if (existingItems.length === 0) {
        const zeroRateHourly = workers.filter(w =>
          w.isActive &&
          (w as any).payType !== "salary" &&
          w.workerType !== "contractor" &&
          !parseFloat((w as any).payRate?.toString() || "0")
        );
        for (const w of zeroRateHourly) {
          flags.push({
            severity: "blocking",
            category: "compensation",
            title: `${w.firstName} ${w.lastName} — Zero pay rate`,
            detail: `This hourly employee has a $0.00/hr pay rate and will be excluded from payroll. Update their compensation before running payroll.`,
            worker: `${w.firstName} ${w.lastName}`,
            fixPath: "/app/employees",
            fixLabel: "Open Employee Profile",
          });
        }
        const missingSetup = workers.filter(w => w.isActive && !w.ssn && w.workerType !== "contractor");
        for (const w of missingSetup) {
          flags.push({
            severity: "warning",
            category: "tax",
            title: `${w.firstName} ${w.lastName} — Missing SSN`,
            detail: `SSN is required for W-2 filing. Add this employee's SSN before year-end reporting.`,
            worker: `${w.firstName} ${w.lastName}`,
            fixPath: "/app/payroll?tab=tax-wizard",
            fixLabel: "Open Tax Setup",
          });
        }
      }

      // ── 6. Derive overall risk ────────────────────────────────────────────
      let overallRisk: "low" | "medium" | "high" = "low";
      if (flags.some(f => f.severity === "blocking")) overallRisk = "high";
      else if (flags.some(f => f.severity === "warning")) overallRisk = "medium";

      // ── 7. AI summary (optional — summarizes rule results, does not invent) ─
      const apiKey = process.env.OPENAI_API_KEY;
      let summary = "";

      if (apiKey && flags.length > 0) {
        try {
          const OpenAI = (await import("openai")).default;
          const openai = new OpenAI({ apiKey });
          const ruleOutput = flags.map(f => `[${f.severity.toUpperCase()}] ${f.title}: ${f.detail}`).join("\n");
          const aiPrompt = `You are summarizing the results of a structured payroll preflight check. The rule engine found these issues:\n\n${ruleOutput}\n\nWrite a 1-2 sentence plain-English summary of what was found and what the payroll manager should do. Do not invent new issues. Do not repeat every flag — just give the overall picture.`;
          const response = await openai.chat.completions.create({
            model: "gpt-4o",
            messages: [{ role: "user", content: aiPrompt }],
            max_tokens: 200,
            temperature: 0.2,
          });
          summary = response.choices[0]?.message?.content?.trim() || "";
        } catch {
          // AI summary failure is non-fatal
        }
      }

      if (!summary) {
        const blocking = flags.filter(f => f.severity === "blocking").length;
        const warnings = flags.filter(f => f.severity === "warning").length;
        const infos = flags.filter(f => f.severity === "info").length;
        if (flags.length === 0) summary = "No issues detected. This payroll run looks ready to process.";
        else if (blocking > 0) summary = `${blocking} blocking issue${blocking !== 1 ? "s" : ""} must be resolved before processing. ${warnings > 0 ? `${warnings} additional warning${warnings !== 1 ? "s" : ""} also require review.` : ""}`.trim();
        else if (warnings > 0) summary = `${warnings} item${warnings !== 1 ? "s" : ""} flagged for review. No blocking issues — payroll can proceed but review recommended.`;
        else summary = `${infos} informational item${infos !== 1 ? "s" : ""} for awareness. Payroll looks ready to process.`;
      }

      // ── 8. Map to legacy flag shape for frontend compatibility ────────────
      const legacyFlags = flags.map(f => ({
        severity: f.severity === "blocking" ? "error" : f.severity === "warning" ? "warning" : "info",
        category: f.category,
        title: f.title,
        detail: f.detail,
        worker: f.worker,
        fixPath: f.fixPath,
        fixLabel: f.fixLabel,
      }));

      res.json({ overallRisk, summary, flags: legacyFlags });
    } catch (error: any) {
      console.error("[Payroll Preflight]", error);
      res.status(500).json({ message: "Preflight review failed: " + (error.message || "Unknown error") });
    }
  });

  app.post("/api/payroll-runs/:id/process", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const processUser = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(processUser?.role) && processUser?.companyId && run.companyId !== processUser.companyId) {
        return res.status(403).json({ message: "Forbidden: payroll run belongs to a different company" });
      }

      if (run.lockedAt || run.isLocked) {
        return res.status(409).json({ message: "Cannot reprocess a locked payroll run." });
      }

      const company = await storage.getCompany(run.companyId);
      if (!company) return res.status(404).json({ message: "Company not found" });

      // ── Duplicate-period guard ──────────────────────────────────────────────
      // Block processing if another finalized run already covers this exact period.
      const conflictRun = (await storage.getPayrollRuns(run.companyId)).find(r =>
        r.id !== run.id &&
        (r.status === "processed" || r.status === "paid") &&
        r.periodStart === run.periodStart &&
        r.periodEnd === run.periodEnd
      );
      if (conflictRun) {
        return res.status(409).json({
          message: `Cannot process: a finalized payroll run already exists for this period ` +
            `(${run.periodStart} – ${run.periodEnd}). Delete or void run #${conflictRun.id.slice(0, 8)} first.`,
          conflictRunId: conflictRun.id,
        });
      }

      // ── Period-alignment pre-flight check ────────────────────────────────────
      // Verify the run's stored periodStart/periodEnd match what the active
      // schedule resolves for this payDate.  Misaligned runs must be repaired
      // via POST /api/payroll-runs/:id/repair-period before processing.
      {
        const schedules = await storage.getPayPeriodSchedules(run.companyId);
        const active = schedules.filter(s => s.isActive);
        if (active.length === 0) {
          return res.status(422).json({
            message: "No active Pay Period Schedule found for this company. " +
              "Activate a schedule in Settings → Pay Period Schedules before processing payroll.",
          });
        }
        if (active.length > 1) {
          return res.status(422).json({
            message: `${active.length} active Pay Period Schedules found — only one may be active at a time. ` +
              "Deactivate the extras in Settings → Pay Period Schedules, then try again.",
            activeScheduleIds: active.map(s => s.id),
          });
        }
        if (run.payDate) {
          const expectedPeriod = resolvePayPeriod(active[0], run.payDate);
          if (expectedPeriod &&
              (expectedPeriod.periodStart !== run.periodStart ||
               expectedPeriod.periodEnd   !== run.periodEnd)) {
            return res.status(422).json({
              message:
                `Period alignment mismatch: the stored period (${run.periodStart} – ${run.periodEnd}) ` +
                `does not match what the active schedule resolves for payDate ${run.payDate} ` +
                `(expected ${expectedPeriod.periodStart} – ${expectedPeriod.periodEnd}). ` +
                `Use POST /api/payroll-runs/${run.id}/repair-period to realign before processing.`,
              stored: { periodStart: run.periodStart, periodEnd: run.periodEnd },
              expected: expectedPeriod,
            });
          }
        }
      }

      // Auto-convert approved punches → time entries before the gate runs.
      // This way "approving timecards" in the attendance view is sufficient;
      // users don't need a separate manual "convert punches" step.
      try {
        const autoConvert = await storage.convertPunchesToTimeEntries(
          run.companyId, run.periodStart, run.periodEnd
        );
        if (autoConvert.created > 0) {
          console.log(`[PAYROLL] Auto-converted ${autoConvert.created} punch group(s) to time entries for period ${run.periodStart}–${run.periodEnd}`);
        }
      } catch (convertErr) {
        console.warn("[PAYROLL] Auto-convert punches warning (non-fatal):", convertErr);
      }

      let entries = await storage.getTimeEntriesByDateRange(
        run.companyId, run.periodStart, run.periodEnd
      );
      // Strip out time entries for volunteer/no-pay positions before any calculations
      const allPositionsForPayroll = await storage.getPositions(run.companyId);
      const volunteerPositionIds = new Set(allPositionsForPayroll.filter((p: any) => p.isVolunteer).map((p: any) => p.id));
      if (volunteerPositionIds.size > 0) {
        entries = entries.filter(e => !(e.positionId && volunteerPositionIds.has(String(e.positionId))));
      }
      // Commission-only positions: hours are tracked but don't generate hourly pay.
      // Commission pay comes separately from the commissions table.
      const commissionPositionIds = new Set(allPositionsForPayroll.filter((p: any) => p.payType === "commission").map((p: any) => p.id));
      if (commissionPositionIds.size > 0) {
        entries = entries.filter(e => !(e.positionId && commissionPositionIds.has(String(e.positionId))));
      }
      const allWorkers = await storage.getWorkers(run.companyId);
      // Treat null as active (handles workers added before the isActive column existed)
      const activeWorkers = allWorkers.filter(w => w.isActive !== false);
      const skippedInactive = allWorkers.filter(w => w.isActive === false);
      if (skippedInactive.length > 0) {
        console.log(`[PAYROLL] Skipping ${skippedInactive.length} inactive worker(s): ${skippedInactive.map(w => `${w.firstName} ${w.lastName}`).join(", ")}`);
      }

      // Include cross-company workers: workers from other companies who have time
      // entries stamped with this company's ID (they worked cross-scheduled shifts).
      const activeWorkerIds = new Set(activeWorkers.map(w => w.id));
      const entryWorkerIds = new Set(entries.map(e => e.workerId));
      const crossCompanyWorkerIds = [...entryWorkerIds].filter(id => !activeWorkerIds.has(id));
      if (crossCompanyWorkerIds.length > 0) {
        const crossWorkers = await Promise.all(crossCompanyWorkerIds.map(id => storage.getWorker(id)));
        const validCrossWorkers = crossWorkers.filter(w => w && w.isActive !== false) as typeof activeWorkers;
        if (validCrossWorkers.length > 0) {
          console.log(`[PAYROLL] Including ${validCrossWorkers.length} cross-company worker(s) with entries for this period: ${validCrossWorkers.map(w => `${w.firstName} ${w.lastName} (home=${w.companyId})`).join(", ")}`);
          activeWorkers.push(...validCrossWorkers);
        }
      }

      const companyDeductions = await storage.getTaxesDeductions(run.companyId);

      // Load existing items early so the gate can exempt manual-override workers
      // and the delete phase can preserve them.
      const existingItemsPreGate = await storage.getPayrollItems(run.id);
      const manualOverrideItems = existingItemsPreGate.filter(i => (i as any).isManualOverride === true);
      const manualOverrideWorkerIds = new Set(manualOverrideItems.map(i => i.workerId));

      // ── Payroll Pipeline Integrity Gate ──────────────────────────────────────
      // Hard-block processing if fundamental requirements are not met.
      // Prevents producing incorrect or incomplete paychecks.
      {
        const gateErrors: Array<{ code: string; message: string; fixPath: string }> = [];

        // 1. Funding source: must have a remittance source with routing + account
        const { remittanceSources: rsTable } = await import("../shared/schema.js");
        const allSources = await db.select().from(rsTable).where(eq(rsTable.companyId, run.companyId));
        const validFundingSource = allSources.find(s => s.routingNumber && s.accountNumber);
        if (!validFundingSource) {
          gateErrors.push({
            code: "no_funding_source",
            message: "No remittance source with routing and account number is configured. Payroll cannot be processed without a funding account.",
            fixPath: "/app/payroll?tab=remittance",
          });
        }

        // 2. Worker compensation: every active worker must have payRate > 0
        //    Exception: commission-only workers get paid via commissions, not payRate
        const workersWithoutPay = activeWorkers.filter(w => {
          const compType = (w as any).compensationType || "hourly";
          if (compType === "commission") return false; // commission workers don't need a payRate
          const rate = parseFloat(String(w.payRate || "0"));
          return rate <= 0;
        });
        if (workersWithoutPay.length > 0) {
          gateErrors.push({
            code: "workers_missing_pay_rate",
            message: `${workersWithoutPay.length} active worker(s) have no pay rate set: ${workersWithoutPay.map(w => `${w.firstName} ${w.lastName}`).join(", ")}.`,
            fixPath: "/app/employees",
          });
        }

        // 3. Hourly workers: must have at least some time entries in the period
        //    Commission workers are exempt from this check
        const hourlyWorkers = activeWorkers.filter(w => {
          const compType = (w as any).compensationType || "hourly";
          if (compType === "commission") return false;
          return w.payType === "hourly" || !w.payType;
        });
        const hourlyWorkerIds = new Set(hourlyWorkers.map(w => w.id));
        // Workers with a manual override are treated as "having entries" — their pay
        // was intentionally set by an admin and does not require underlying time entries.
        const workerIdsWithEntries = new Set([
          ...entries.map(e => e.workerId),
          ...manualOverrideWorkerIds,
        ]);
        const hourlyWithNoEntries = hourlyWorkers.filter(w =>
          hourlyWorkerIds.has(w.id) && !workerIdsWithEntries.has(w.id)
        );
        if (hourlyWithNoEntries.length > 0 && hourlyWorkers.length > 0 && hourlyWithNoEntries.length === hourlyWorkers.length) {
          // Only block if ALL hourly workers have zero entries (likely forgot to approve/convert)
          gateErrors.push({
            code: "no_time_entries",
            message: `No time entries found for this pay period (${run.periodStart} – ${run.periodEnd}). If employees used the time clock, go to Attendance → Timesheets, approve the punches, then return here and try again. If you entered hours manually, create time entries in the Timesheets tab first.`,
            fixPath: "/app/attendance?tab=timesheet",
          });
        }

        if (gateErrors.length > 0) {
          return res.status(422).json({
            message: "Payroll cannot be processed — integrity requirements not met.",
            errors: gateErrors,
          });
        }
      }
      // ── End Integrity Gate ───────────────────────────────────────────────────

      // Preserve manual-override items; delete only auto-calculated ones.
      // Manual overrides are payroll items an admin intentionally edited — their
      // hours and amounts must survive re-processing so the check matches expectations.
      for (const old of existingItemsPreGate) {
        if (!(old as any).isManualOverride) {
          await storage.deletePayrollItem(old.id);
        }
      }

      // Pre-seed run totals with the values from preserved manual-override items
      // so the final run totals include both auto and manually-set pay.
      let totalGross = 0, totalNet = 0, totalHours = 0, totalOT = 0;
      // Atomically reserve a block of check numbers using a transaction-level advisory lock.
      // pg_advisory_xact_lock releases automatically on commit/rollback, preventing leaks on pooled connections.
      // Compute the highest check number already used by manual-override items so the
      // advisory-lock reservation covers the full range before any concurrent run reads it.
      const maxManualCheck = manualOverrideItems.reduce((max, mi) => {
        const n = parseInt((mi as any).checkNumber || "0", 10);
        return Math.max(max, n);
      }, 0);
      const nonOverrideCount = activeWorkers.filter(w => !manualOverrideWorkerIds.has(w.id)).length;

      const _checkNumStart = await db.transaction(async (tx) => {
        await tx.execute(sql`SELECT pg_advisory_xact_lock(abs(hashtext(${run.companyId}))::bigint)`);
        const _r = await tx.execute(sql`SELECT next_check_number FROM companies WHERE id = ${run.companyId} FOR UPDATE`);
        const _s = Number((((_r as any).rows || (_r as any))[0])?.next_check_number || 1);
        // startFrom skips past all manual-override check numbers so auto-assignment never overlaps them.
        const startFrom = Math.max(_s, maxManualCheck + 1);
        // Reserve exactly enough numbers for non-override workers (no extra buffer to prevent numbering gaps).
        await tx.execute(sql`UPDATE companies SET next_check_number = ${startFrom + nonOverrideCount} WHERE id = ${run.companyId}`);
        return startFrom;
      });
      let checkNum = _checkNumStart;
      for (const mi of manualOverrideItems) {
        totalGross += parseFloat((mi as any).grossPay || "0");
        totalNet   += parseFloat((mi as any).netPay   || "0");
        totalHours += parseFloat((mi as any).regularHours  || "0") + parseFloat((mi as any).overtimeHours || "0") + parseFloat((mi as any).doubleTimeHours || "0");
        totalOT    += parseFloat((mi as any).overtimeHours || "0");
        // Tally the manual item's totals; check number reservation was already handled above.
      }

      const existingYtdByWorker: Record<string, { gross: number; deductions: number; net: number }> = {};

      const allRuns = await storage.getPayrollRuns(run.companyId);
      // YTD year is anchored to the payDate (check date) — falls back to periodStart year.
      // YTD floor is Jan 1 of that year so cross-year periods (e.g. Dec 29 – Jan 4) are handled correctly.
      const ytdYear = run.payDate
        ? new Date(run.payDate + "T00:00:00").getFullYear()
        : new Date(run.periodStart).getFullYear();
      const ytdFloor = `${ytdYear}-01-01`;
      const priorRunsRaw = allRuns.filter(r =>
        (r.status === "processed" || r.status === "paid") &&
        r.id !== run.id &&
        r.periodEnd < run.periodStart &&
        r.periodEnd >= ytdFloor
      );
      // Deduplicate: if multiple processed/paid runs cover the same period, count only one.
      // Keeps "paid" over "processed"; within same status keeps the latest processedAt.
      const priorRuns = deduplicateByPeriod(priorRunsRaw);

      for (const worker of activeWorkers) {
        let ytdGross = 0, ytdDeductions = 0, ytdNet = 0;
        for (const pr of priorRuns) {
          const priorItems = await storage.getPayrollItems(pr.id);
          const workerItem = priorItems.find(i => i.workerId === worker.id);
          if (workerItem) {
            ytdGross += parseFloat(workerItem.grossPay || "0");
            ytdDeductions += parseFloat(workerItem.deductions || "0");
            ytdNet += parseFloat(workerItem.netPay || "0");
          }
        }
        existingYtdByWorker[worker.id] = { gross: ytdGross, deductions: ytdDeductions, net: ytdNet };
      }

      const items: any[] = [];
      const workerTaxLines: Record<string, ReturnType<typeof calcAllTaxes>["lines"]> = {};
      // Captures full tax engine inputs per worker for audit snapshot reproducibility
      const workerDeductionBreakdown: Record<string, { preTaxDedAmount: number; customPostTaxDed: number; amendmentDeductions: number; taxEngineInput: TaxEngineInput }> = {};

      const allWageGroups = await storage.getSecondaryWageGroups(run.companyId);
      const wageGroupMap: Record<string, { hourlyRate: number; overtimeRate: number }> = {};
      for (const wg of allWageGroups) {
        wageGroupMap[wg.id] = {
          hourlyRate: parseFloat(wg.hourlyRate || "0"),
          overtimeRate: parseFloat(wg.overtimeRate || "0"),
        };
      }

      // Load active pay period schedule for salary and period resolution
      const companySchedules = await storage.getPayPeriodSchedules(run.companyId);
      const activeSchedule = companySchedules.find(s => s.isActive);
      const schedulePeriodsPerYear = activeSchedule
        ? periodsPerYearFromSchedule(activeSchedule.type)
        : periodsPerYearFromSchedule(company.payFrequency || "biweekly");

      // Load approved commissions for this period (keyed by workerId)
      const { commissions: commissionsTable } = await import("../shared/schema.js");
      const periodCommissions = await db.select().from(commissionsTable).where(
        and(
          eq(commissionsTable.companyId, run.companyId),
          eq(commissionsTable.status, "approved"),
          gte(commissionsTable.earnedDate, run.periodStart),
          lte(commissionsTable.earnedDate, run.periodEnd)
        )
      );
      const commissionsByWorker: Record<string, typeof periodCommissions> = {};
      for (const c of periodCommissions) {
        if (!commissionsByWorker[c.workerId]) commissionsByWorker[c.workerId] = [];
        commissionsByWorker[c.workerId].push(c);
      }

      // Load amendments and pay stub accounts for this pay period
      const allAmendments = await storage.getPayStubAmendments(run.companyId);
      console.log(`[PAYROLL] Run ${run.id} period: ${run.periodStart} -> ${run.periodEnd}`);
      console.log(`[PAYROLL] Total amendments for company: ${allAmendments.length}`);
      allAmendments.forEach(a => {
        const effDate = a.effectiveDate ? String(a.effectiveDate) : null;
        const pStart = String(run.periodStart);
        const pEnd = String(run.periodEnd);
        const inPeriod = !effDate || (effDate >= pStart && effDate <= pEnd);
        console.log(`[PAYROLL] Amendment ${a.id}: worker=${a.workerId} type=${(a as any).amendmentType} amount=${a.amount} status=${a.status} effectiveDate=${effDate} (type: ${typeof a.effectiveDate}) periodStart=${pStart} periodEnd=${pEnd} inPeriod=${inPeriod}`);
      });
      const periodAmendments = allAmendments.filter(a => {
        const effDate = a.effectiveDate ? String(a.effectiveDate) : null;
        const endDate = (a as any).endDate ? String((a as any).endDate) : null;
        const isRecurring = (a as any).isRecurring === true;
        // Non-recurring amendments that were already applied to ANY prior run are skipped.
        // Recurring amendments re-apply every period within their date range.
        const alreadyApplied = !isRecurring && (a as any).appliedPayrollRunId && (a as any).appliedPayrollRunId !== run.id;
        if (alreadyApplied) return false;
        // Date-range guard
        const inPeriodStart = !effDate || effDate <= String(run.periodEnd);
        const inPeriodEnd = !endDate || endDate >= String(run.periodStart);
        return a.status === "active" && inPeriodStart && inPeriodEnd;
      });
      console.log(`[PAYROLL] Period amendments after filter: ${periodAmendments.length}`);
      const appliedAmendmentIds: string[] = [];
      const allPsAccounts = await storage.getPayStubAccounts(run.companyId);
      const psAccountMap: Record<string, string> = {};
      for (const acc of allPsAccounts) { psAccountMap[acc.id] = acc.type || "earning"; }

      console.log(`[PAYROLL] Run ${run.id}: ${activeWorkers.length} active worker(s) to process for ${run.periodStart}–${run.periodEnd}: ${activeWorkers.map(w => `${w.firstName} ${w.lastName}`).join(", ")}`);

      for (const worker of activeWorkers) {
        // Skip workers whose payroll item was manually overridden — their preserved
        // item is already included in totals and doesn't need recalculation.
        if (manualOverrideWorkerIds.has(worker.id)) {
          console.log(`[PAYROLL] Skipping ${worker.firstName} ${worker.lastName} — manual override preserved`);
          continue;
        }
        const workerEntries = entries.filter(e => e.workerId === worker.id);
        console.log(`[PAYROLL] Processing worker: ${worker.firstName} ${worker.lastName} (id=${worker.id}, isActive=${worker.isActive}, workerGroup=${(worker as any).workerGroup || "unset"}, entries=${workerEntries.length})`);
        // ── Diagnostic: log raw DB pay_category for every entry (before fallback) ──
        console.log(`[PAYROLL] ${worker.firstName} ${worker.lastName}: ${workerEntries.length} entries in period`);
        for (const e of workerEntries) {
          const rawCat = (e as any).payCategory;
          console.log(`[PAYROLL]   RAW entry id=${e.id} date=${e.date} pay_category_db=${JSON.stringify(rawCat)} totalHours=${e.totalHours} overtimeHours=${e.overtimeHours}`);
        }

        const defaultRate = parseFloat(worker.payRate || "0");
        const otMultiplier = parseFloat(company.overtimeMultiplier || "1.5");

        // ── Unified calculator: all 15 pay categories, both hourly and salary ──
        // This is the ONLY place payroll math runs in the process route.
        // No inline salary/hourly branching — calculateWorkerPay() handles both.
        const processCalcResult = calculateWorkerPay(
          { id: worker.id, payType: worker.payType || "hourly", payRate: worker.payRate || "0" },
          workerEntries.map(e => ({
            workerId: e.workerId,
            totalHours: e.totalHours || "0",
            overtimeHours: e.overtimeHours || "0",
            doubleTimeHours: (e as any).doubleTimeHours || "0",
            payCategory: (e as any).payCategory,
            overridePayRate: (e as any).overridePayRate,
            wageGroupId: e.wageGroupId,
            tipsAmount: (e as any).tipsAmount,
          })),
          {
            overtimeMultiplier: otMultiplier,
            periodsPerYear: schedulePeriodsPerYear,
            wageGroups: wageGroupMap,
          }
        );
        let regHrs             = processCalcResult.regularHours;
        let otHrs              = processCalcResult.overtimeHours;
        let dtHrs              = processCalcResult.doubleTimeHours;
        let regPay             = processCalcResult.regularPay;
        let otPay              = processCalcResult.overtimePay;
        let dtPay              = processCalcResult.doubleTimePay;
        let commissionHrsTotal = processCalcResult.commissionHours;
        let commissionHrlyPay  = processCalcResult.commissionHourlyPay;
        let volunteerHrsTotal  = processCalcResult.volunteerHours;
        let specialEventHrsTotal = processCalcResult.specialEventHours;
        let specialEventPayTotal = processCalcResult.specialEventPay;
        let grossPay             = processCalcResult.grossPay;
        console.log(`[PAYROLL] ${worker.payType === "salary" ? "SALARY" : "HOURLY"} workerId=${worker.id} regHrs=${regHrs.toFixed(2)} otHrs=${otHrs.toFixed(2)} commHrs=${commissionHrsTotal.toFixed(2)} salaryPay=${processCalcResult.salaryPay.toFixed(2)} grossPay=${grossPay.toFixed(2)}`);

        // Apply pay stub amendments for this worker in this pay period
        const workerAmendments = periodAmendments.filter(a => a.workerId === worker.id);
        console.log(`[PAYROLL] Worker ${worker.firstName} ${worker.lastName}: ${workerAmendments.length} amendments`);
        let amendmentEarnings = 0;
        let amendmentDeductions = 0;
        for (const am of workerAmendments) {
          let amAmt = 0;
          if (am.amountType === "percentage") {
            amAmt = grossPay * (parseFloat(am.percent || "0") / 100);
          } else if (parseFloat(am.rate || "0") > 0 && parseFloat(am.units || "0") > 0) {
            amAmt = parseFloat(am.rate) * parseFloat(am.units);
          } else {
            amAmt = parseFloat(am.amount || "0");
          }
          // Use explicit amendmentType first, fall back to account type
          const accountType = am.payStubAccountId ? (psAccountMap[am.payStubAccountId] || "earning") : "earning";
          const effectiveType = (am as any).amendmentType || accountType;
          console.log(`[PAYROLL]   Amendment: amount=${amAmt} effectiveType=${effectiveType} raw_amendmentType=${(am as any).amendmentType}`);
          if (effectiveType === "deduction") {
            amendmentDeductions += amAmt;
          } else {
            amendmentEarnings += amAmt;
          }
          appliedAmendmentIds.push(am.id);
        }
        console.log(`[PAYROLL] Worker ${worker.firstName}: earnings_adj=${amendmentEarnings} deductions_adj=${amendmentDeductions} grossBefore=${grossPay}`);
        grossPay += amendmentEarnings;

        // ── Commission earnings ──
        const workerCommissions = commissionsByWorker[worker.id] || [];
        const commissionPay = workerCommissions.reduce((sum, c) => sum + parseFloat(c.amount || "0"), 0);
        // Add commission hours recorded on commission records themselves (in addition to time-entry commission_hours)
        const commissionRecordHrs = workerCommissions.reduce((sum, c) => sum + parseFloat((c as any).hours || "0"), 0);
        if (commissionRecordHrs > 0) {
          commissionHrsTotal += commissionRecordHrs;
          console.log(`[PAYROLL] Worker ${worker.firstName}: adding ${commissionRecordHrs.toFixed(2)} commission hours from commission records`);
        }
        if (commissionPay > 0) {
          grossPay += commissionPay;
          console.log(`[PAYROLL] Worker ${worker.firstName}: adding commission pay $${commissionPay.toFixed(2)}`);
        }

        const rate = defaultRate;

        const isContractor = worker.workerType === "contractor";
        const workerGroup = (worker as any).workerGroup || (isContractor ? "hourly_contractor" : "hourly_employee");
        const isContractorGroup = workerGroup === "hourly_contractor" || workerGroup === "invoiced_contractor";
        const isVolunteer = workerGroup === "volunteer";
        const isOwnerDist = workerGroup === "owner_distribution";

        if (isVolunteer) {
          console.log(`[PAYROLL] Skipping volunteer worker: ${worker.firstName} ${worker.lastName} (workerGroup="${workerGroup}")`);
          continue;
        }

        const ytd = existingYtdByWorker[worker.id] || { gross: 0, deductions: 0, net: 0 };

        // ── Tax Engine integration ──────────────────────────────────────────────
        // Step 1: Pre-tax deductions reduce federal/state taxable wages before bracket calc
        const preTaxDedRecords = (isContractor || isContractorGroup) ? [] : companyDeductions.filter(d =>
          d.isActive && !d.isEmployerPaid && !d.isReferenceOnly &&
          d.deductionTiming === "pre_tax" &&
          (d.appliesTo || "all") !== "contractor"
        );
        const preTaxDedAmount = preTaxDedRecords.reduce((s, d) => {
          if (d.calculationType === "percentage") return s + grossPay * (parseFloat(d.rate || "0") / 100);
          return s + parseFloat(d.rate || "0");
        }, 0);

        // Step 1b: Taxable benefits add to taxable wage base; reimbursements from deduction records reduce it
        const taxableBenefitsAmount = (isContractor || isContractorGroup) ? 0 : companyDeductions
          .filter(d => d.isActive && !d.isReferenceOnly && d.isTaxableBenefit === true)
          .reduce((s, d) => {
            if (d.calculationType === "percentage") return s + grossPay * (parseFloat(d.rate || "0") / 100);
            return s + parseFloat(d.rate || "0");
          }, 0);
        const reimbursementsFromDeductions = (isContractor || isContractorGroup) ? 0 : companyDeductions
          .filter(d => d.isActive && !d.isReferenceOnly && d.isReimbursement === true)
          .reduce((s, d) => {
            if (d.calculationType === "percentage") return s + grossPay * (parseFloat(d.rate || "0") / 100);
            return s + parseFloat(d.rate || "0");
          }, 0);

        // Step 2: Run the tax engine (federal + CA)
        const taxEngineInput: TaxEngineInput = {
          grossWages: grossPay,
          preTaxDeductions: preTaxDedAmount,
          reimbursements: (processCalcResult.reimburseAmount || 0) + reimbursementsFromDeductions,
          taxableBenefits: taxableBenefitsAmount,
          ytdGross: ytd.gross,
          ytdFedTaxableWages: ytd.gross,
          filingStatus: (worker.w4FilingStatus || "single") as FilingStatus,
          w4Allowances: parseInt(String(worker.w4Allowances ?? 0), 10),
          additionalWithholding: parseFloat(String(worker.additionalWithholding || "0")),
          caFilingStatus: (worker.w4FilingStatus || "single") as FilingStatus,
          caAllowances: parseInt(String(worker.w4Allowances ?? 0), 10),
          payPeriodType: payPeriodTypeFromSchedule(activeSchedule?.type),
          isContractor: isContractor || isContractorGroup,
        };
        const taxResult = calcAllTaxes(taxEngineInput, true);
        workerTaxLines[worker.id] = taxResult.lines;

        // Step 3: Custom post-tax non-statutory deductions (benefits, garnishments, etc.)
        const customPostTaxDedRecords = (isContractor || isContractorGroup) ? [] : companyDeductions.filter(d => {
          if (!d.isActive || d.isEmployerPaid || d.isReferenceOnly) return false;
          if ((d.appliesTo || "all") === "contractor") return false;
          if (d.taxCode) return false; // engine already handles statutory taxes
          if (d.deductionTiming === "pre_tax") return false; // already counted above in preTaxDedAmount
          const nameLower = d.name.toLowerCase();
          if (nameLower.includes("se tax") || nameLower.includes("self-employment") || nameLower.includes("self employment")) return false;
          return true;
        });
        const customPostTaxDed = customPostTaxDedRecords.reduce((s, d) => {
          if (d.calculationType === "percentage") {
            if (d.maxAmount) {
              const wageCap = parseFloat(d.maxAmount);
              const remainingCap = Math.max(0, wageCap - ytd.gross);
              const base = Math.min(grossPay, remainingCap);
              return s + base * (parseFloat(d.rate || "0") / 100);
            }
            return s + grossPay * (parseFloat(d.rate || "0") / 100);
          }
          return s + parseFloat(d.rate || "0");
        }, 0);

        // totalDeductions = pre-tax deductions (401k etc.) + engine employee taxes + custom post-tax deductions + amendment deductions
        // Pre-tax deductions reduce taxable wages AND come out of the employee's paycheck (net pay)
        let totalDeductions = preTaxDedAmount + taxResult.employeeTaxTotal + customPostTaxDed + amendmentDeductions;

        // Save full inputs for audit snapshot and non-tax deduction line storage
        workerDeductionBreakdown[worker.id] = { preTaxDedAmount, customPostTaxDed, amendmentDeductions, taxEngineInput };

        const netPay = grossPay - totalDeductions;

        console.log(`[PAYROLL] ${worker.firstName} ${worker.lastName}: regHrs=${regHrs.toFixed(2)} otHrs=${otHrs.toFixed(2)} dtHrs=${dtHrs.toFixed(2)} commHrs=${commissionHrsTotal.toFixed(2)} regPay=${regPay.toFixed(2)} commHrlyPay=${commissionHrlyPay.toFixed(2)} commPay=${commissionPay.toFixed(2)} grossPay=${grossPay.toFixed(2)}`);
        for (const e of workerEntries) {
          const eCat = (e as any).payCategory || "regular";
          console.log(`[PAYROLL]   entry id=${e.id} date=${e.date} payCategory=${eCat} totalHours=${e.totalHours} countedAs=${eCat === "commission_hours" ? "commission" : eCat === "volunteer" ? "volunteer" : eCat === "special_event" ? "special_event" : "regular"}`);
        }

        totalGross += grossPay;
        totalNet += netPay;
        totalHours += regHrs + otHrs + dtHrs + commissionHrsTotal;
        totalOT += otHrs;

        items.push({
          payrollRunId: run.id,
          workerId: worker.id,
          regularHours: regHrs.toFixed(2),
          overtimeHours: otHrs.toFixed(2),
          doubleTimeHours: dtHrs.toFixed(2),
          // regularPay: salary base kept here for backward compat; salaryPay column is additional detail
          regularPay: (regPay + processCalcResult.salaryPay).toFixed(2),
          overtimePay: otPay.toFixed(2),
          doubleTimePay: dtPay.toFixed(2),
          grossPay: grossPay.toFixed(2),
          deductions: totalDeductions.toFixed(2),
          netPay: netPay.toFixed(2),
          payRate: rate.toFixed(2),
          payType: worker.payType || "hourly",
          checkNumber: String(checkNum++),
          ytdGross: (ytd.gross + grossPay).toFixed(2),
          ytdDeductions: (ytd.deductions + totalDeductions).toFixed(2),
          ytdNet: (ytd.net + netPay).toFixed(2),
          commissionPay: commissionPay > 0 ? commissionPay.toFixed(2) : undefined,
          commissionHours: commissionHrsTotal > 0 ? commissionHrsTotal.toFixed(2) : "0",
          commissionHourlyPay: commissionHrlyPay > 0 ? commissionHrlyPay.toFixed(2) : "0",
          volunteerHours: volunteerHrsTotal > 0 ? volunteerHrsTotal.toFixed(2) : "0",
          specialEventHours: specialEventHrsTotal > 0 ? specialEventHrsTotal.toFixed(2) : "0",
          specialEventPay: specialEventPayTotal > 0 ? specialEventPayTotal.toFixed(2) : "0",
          // ── All 15 categories (Task 2) ────────────────────────────────────
          salaryPay: processCalcResult.salaryPay > 0 ? processCalcResult.salaryPay.toFixed(2) : "0",
          bonusPay: processCalcResult.bonusPay > 0 ? processCalcResult.bonusPay.toFixed(2) : "0",
          tipsPay: processCalcResult.tipsPay > 0 ? processCalcResult.tipsPay.toFixed(2) : "0",
          reimburseAmount: processCalcResult.reimburseAmount > 0 ? processCalcResult.reimburseAmount.toFixed(2) : "0",
          ptoHours: processCalcResult.ptoHours > 0 ? processCalcResult.ptoHours.toFixed(2) : "0",
          ptoPay: processCalcResult.ptoPay > 0 ? processCalcResult.ptoPay.toFixed(2) : "0",
          sickHours: processCalcResult.sickHours > 0 ? processCalcResult.sickHours.toFixed(2) : "0",
          sickPay: processCalcResult.sickPay > 0 ? processCalcResult.sickPay.toFixed(2) : "0",
          holidayHours: processCalcResult.holidayHours > 0 ? processCalcResult.holidayHours.toFixed(2) : "0",
          holidayPay: processCalcResult.holidayPay > 0 ? processCalcResult.holidayPay.toFixed(2) : "0",
          unpaidHours: processCalcResult.unpaidHours > 0 ? processCalcResult.unpaidHours.toFixed(2) : "0",
          unpaidDeduction: processCalcResult.unpaidDeduction > 0 ? processCalcResult.unpaidDeduction.toFixed(2) : "0",
        });
      }

      const snapshotWorkerData: any[] = [];
      for (const item of items) {
        const created = await storage.createPayrollItem(item);
        // Persist per-item tax lines from the engine
        const lines = workerTaxLines[item.workerId] || [];
        const dedBreakdown = workerDeductionBreakdown[item.workerId];
        // Clear any stale tax lines (re-processing scenario)
        await storage.deletePayrollItemTaxesByItem(created.id);
        for (const line of lines) {
          await storage.createPayrollItemTax({
            payrollItemId: created.id,
            taxCode: line.taxCode,
            taxName: line.taxName,
            taxableWages: String(line.taxableWages),
            rate: String(line.rate),
            amount: String(line.amount),
            isEmployerPaid: line.isEmployerPaid,
            stateCode: line.stateCode ?? null,
          });
        }
        // Store non-statutory deductions as typed lines so that
        // SUM(payroll_item_taxes.amount WHERE isEmployerPaid=false) == payroll_items.deductions
        // This makes the tables consistent for downstream reconciliation.
        if (dedBreakdown) {
          if (dedBreakdown.preTaxDedAmount > 0) {
            await storage.createPayrollItemTax({
              payrollItemId: created.id,
              taxCode: "PRE_TAX_DED",
              taxName: "Pre-Tax Deductions",
              taxableWages: "0", rate: "0",
              amount: dedBreakdown.preTaxDedAmount.toFixed(2),
              isEmployerPaid: false, stateCode: null,
            });
          }
          if (dedBreakdown.customPostTaxDed > 0) {
            await storage.createPayrollItemTax({
              payrollItemId: created.id,
              taxCode: "POST_TAX_DED",
              taxName: "Post-Tax Deductions",
              taxableWages: "0", rate: "0",
              amount: dedBreakdown.customPostTaxDed.toFixed(2),
              isEmployerPaid: false, stateCode: null,
            });
          }
          if (dedBreakdown.amendmentDeductions > 0) {
            await storage.createPayrollItemTax({
              payrollItemId: created.id,
              taxCode: "AMENDMENT_DED",
              taxName: "Pay Adjustments",
              taxableWages: "0", rate: "0",
              amount: dedBreakdown.amendmentDeductions.toFixed(2),
              isEmployerPaid: false, stateCode: null,
            });
          }
        }
        snapshotWorkerData.push({
          workerId: item.workerId,
          grossPay: item.grossPay,
          // Full tax engine inputs for deterministic audit replay
          taxableWages: dedBreakdown
            ? (parseFloat(item.grossPay || "0") - dedBreakdown.preTaxDedAmount).toFixed(2)
            : item.grossPay,
          filingStatus: dedBreakdown?.taxEngineInput.filingStatus ?? "single",
          w4Allowances: dedBreakdown?.taxEngineInput.w4Allowances ?? 0,
          additionalWithholding: dedBreakdown?.taxEngineInput.additionalWithholding ?? 0,
          preTaxDeductions: dedBreakdown ? dedBreakdown.preTaxDedAmount.toFixed(2) : "0",
          postTaxDeductions: dedBreakdown ? dedBreakdown.customPostTaxDed.toFixed(2) : "0",
          amendmentDeductions: dedBreakdown ? dedBreakdown.amendmentDeductions.toFixed(2) : "0",
          payPeriodType: dedBreakdown?.taxEngineInput.payPeriodType ?? "biweekly",
          ytdGross: dedBreakdown ? dedBreakdown.taxEngineInput.ytdGross.toFixed(2) : "0",
          // Full TaxEngineInput modifiers for complete reproducibility
          reimbursements: dedBreakdown ? dedBreakdown.taxEngineInput.reimbursements.toFixed(2) : "0",
          taxableBenefits: dedBreakdown ? dedBreakdown.taxEngineInput.taxableBenefits.toFixed(2) : "0",
          ytdFedTaxableWages: dedBreakdown ? dedBreakdown.taxEngineInput.ytdFedTaxableWages.toFixed(2) : "0",
          employerCaUiRate: dedBreakdown?.taxEngineInput.employerCaUiRate ?? null,
          caFilingStatus: dedBreakdown?.taxEngineInput.caFilingStatus ?? "single",
          caAllowances: dedBreakdown?.taxEngineInput.caAllowances ?? 0,
          isContractor: dedBreakdown?.taxEngineInput.isContractor ?? false,
          taxLines: lines,
        });
      }

      // ── Write tax snapshot for this run ───────────────────────────────────
      try {
        await storage.upsertPayrollTaxSnapshot(
          run.id,
          run.companyId,
          JSON.stringify({ runId: run.id, engineVersion: TAX_ENGINE_VERSION, processedAt: new Date().toISOString(), workers: snapshotWorkerData }),
          TAX_ENGINE_VERSION,
        );
      } catch (snapErr) {
        console.warn("[TAX] Failed to write tax snapshot:", snapErr);
      }

      // ── Mark paid commissions ────────────────────────────────────────────
      const paidRunId = run.id;
      const commissionIdsToMark: string[] = [];
      for (const wComms of Object.values(commissionsByWorker)) {
        for (const c of wComms) commissionIdsToMark.push(c.id);
      }
      if (commissionIdsToMark.length > 0) {
        await db.update(commissionsTable)
          .set({ status: "paid", payrollRunId: paidRunId, paidAt: new Date() } as any)
          .where(inArray(commissionsTable.id, commissionIdsToMark));
        console.log(`[PAYROLL] Marked ${commissionIdsToMark.length} commission(s) as paid for run ${paidRunId}`);
      }

      // ── Mark non-recurring amendments as applied to prevent double-apply ──
      const appliedNow = new Date();
      const uniqueAppliedIds = [...new Set(appliedAmendmentIds)];
      for (const amId of uniqueAppliedIds) {
        const am = allAmendments.find(a => a.id === amId);
        if (am && !(am as any).isRecurring) {
          await storage.updatePayStubAmendment(amId, {
            appliedPayrollRunId: run.id,
            appliedAt: appliedNow,
          } as any);
        }
      }

      // Use GREATEST to advance the counter to the last number used without ever rewinding.
      // The pre-allocation transaction may have set it higher (concurrent run); GREATEST is safe.
      await db.execute(sql`UPDATE companies SET next_check_number = GREATEST(next_check_number, ${checkNum}) WHERE id = ${run.companyId}`);

      const prevProcessStatus = run.status;
      await storage.updatePayrollRun(run.id, {
        status: "processed",
        totalGross: totalGross.toFixed(2),
        totalNet: totalNet.toFixed(2),
        totalHours: totalHours.toFixed(2),
        totalOvertimeHours: totalOT.toFixed(2),
        workerCount: activeWorkers.length,
        processedAt: new Date(),
        needsRecalculation: false,
      } as any);

      // Audit log for the process transition (lifecycle requirement)
      try {
        await storage.createPayrollPaymentAuditLog({
          companyId: run.companyId,
          payrollRunId: run.id,
          actorId: req.session.userId || null,
          event: "processed",
          previousStatus: prevProcessStatus,
          newStatus: "processed",
          notes: `Processed ${activeWorkers.length} worker(s); total net $${totalNet.toFixed(2)}`,
        });
      } catch (auditErr) {
        console.error("[PAYROLL] Process transition audit error:", auditErr);
      }

      // ── Auto-generate payroll summary ──────────────────────────────────────
      try {
        const createdItems = await storage.getPayrollItems(run.id);
        // Group by paymentMethod for the payment-method breakout
        const pmGroups: Record<string, { count: number; amount: number }> = {};
        let summaryDeductions = 0;
        for (const ci of createdItems) {
          const pm = (ci.paymentMethod || "check").toLowerCase();
          if (!pmGroups[pm]) pmGroups[pm] = { count: 0, amount: 0 };
          pmGroups[pm].count++;
          pmGroups[pm].amount += parseFloat(ci.netPay || "0");
          summaryDeductions += parseFloat(ci.deductions || "0");
        }
        // Compute employer taxes from company tax/deduction records (employer-paid only)
        const employerTaxRecords = companyDeductions.filter(d => d.isActive && d.isEmployerPaid && !d.isReferenceOnly);
        let totalEmployerTaxes = 0;
        for (const etd of employerTaxRecords) {
          if (etd.calculationType === "percentage") {
            totalEmployerTaxes += totalGross * (parseFloat(etd.rate || "0") / 100);
          } else {
            totalEmployerTaxes += parseFloat(etd.rate || "0") * createdItems.length;
          }
        }
        // ── Real reimbursements: sum approved expenses for this pay period ──
        let totalReimbursements = 0;
        try {
          const periodExpenses = await storage.getExpenses(run.companyId);
          const approvedReimbursements = periodExpenses.filter(e =>
            e.reimbursementRequested &&
            (e.reimbursementStatus === "approved" || e.status === "approved") &&
            e.expenseDate >= run.periodStart &&
            e.expenseDate <= run.periodEnd
          );
          totalReimbursements = approvedReimbursements.reduce((sum, e) => sum + parseFloat(e.amount || "0"), 0);
        } catch (reimErr) {
          console.warn("[PAYROLL] Could not load reimbursements:", reimErr);
        }

        const summary = await storage.upsertPayrollSummary(run.id, {
          companyId: run.companyId,
          totalGross: totalGross.toFixed(2),
          totalDeductions: summaryDeductions.toFixed(2),
          totalNet: totalNet.toFixed(2),
          totalEmployerTaxes: totalEmployerTaxes.toFixed(2),
          totalReimbursements: totalReimbursements.toFixed(2),
          totalFundingRequired: (totalNet + totalEmployerTaxes + totalReimbursements).toFixed(2),
          achCount: pmGroups["ach"]?.count || pmGroups["direct_deposit"]?.count || 0,
          achAmount: ((pmGroups["ach"]?.amount || 0) + (pmGroups["direct_deposit"]?.amount || 0)).toFixed(2),
          checkCount: pmGroups["check"]?.count || 0,
          checkAmount: (pmGroups["check"]?.amount || 0).toFixed(2),
          cashCount: pmGroups["cash"]?.count || 0,
          cashAmount: (pmGroups["cash"]?.amount || 0).toFixed(2),
          tradeCount: pmGroups["trade"]?.count || 0,
          tradeAmount: (pmGroups["trade"]?.amount || 0).toFixed(2),
          otherCount: Object.entries(pmGroups).filter(([k]) => !["ach","direct_deposit","check","cash","trade"].includes(k)).reduce((s,[,v])=>s+v.count,0),
          otherAmount: Object.entries(pmGroups).filter(([k]) => !["ach","direct_deposit","check","cash","trade"].includes(k)).reduce((s,[,v])=>s+v.amount,0).toFixed(2),
          workerCount: createdItems.length,
        });
        await storage.updatePayrollRun(run.id, { payrollSummaryId: summary.id });
      } catch (summaryErr) {
        console.error("Failed to generate payroll summary:", summaryErr);
      }

      // ── Auto-generate payroll transaction runs ─────────────────────────────
      try {
        await storage.deletePayrollTransactionRunsByRun(run.id);
        const createdItems = await storage.getPayrollItems(run.id);
        for (const ci of createdItems) {
          await storage.createPayrollTransactionRun({
            payrollRunId: run.id,
            payrollItemId: ci.id,
            workerId: ci.workerId,
            companyId: run.companyId,
            paymentMethod: ci.paymentMethod || "check",
            netPay: ci.netPay || "0",
            payDate: run.payDate || null,
            status: "approved",
            fundingAccountId: run.fundingAccountId || null,
            checkNumber: ci.checkNumber || null,
            achBatchId: null,
          });
        }
      } catch (txnErr) {
        console.error("Failed to generate payroll transaction runs:", txnErr);
      }

      const updatedRun = await storage.getPayrollRun(run.id);
      const finalItems = await storage.getPayrollItems(run.id);

      try {
        const users = await storage.getUsers();
        const companyUsers = users.filter(u => u.companyId === run.companyId && u.isActive !== false);
        for (const u of companyUsers) {
          await storage.createNotification({
            companyId: run.companyId,
            userId: u.id,
            type: "payroll_processed",
            title: "Payroll Processed",
            message: `Payroll for ${run.periodStart} – ${run.periodEnd} has been processed.`,
            actionUrl: "/payroll",
            isRead: false,
          });
        }
      } catch (notifErr) {
        console.error("Failed to dispatch payroll notifications:", notifErr);
      }

      res.json({ run: updatedRun, items: finalItems });
    } catch (error: any) {
      console.error("Payroll processing error:", error);
      const detail = error?.message || String(error);
      res.status(500).json({ message: "Failed to process payroll", detail });
    }
  });

  // ── Approve Payroll Run ────────────────────────────────────────────────────
  app.post("/api/payroll-runs/:id/approve", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const approveUser = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(approveUser?.role) && approveUser?.companyId && run.companyId !== approveUser.companyId) {
        return res.status(403).json({ message: "Forbidden: payroll run belongs to a different company" });
      }
      if (run.status !== "processed") return res.status(400).json({ message: "Payroll run must be processed before approving" });
      if (run.lockedAt || run.isLocked) return res.status(400).json({ message: "Payroll run is locked and cannot be modified" });

      // ── Server-side compliance preflight gate ────────────────────────────
      try {
        const companyProfile = await storage.getCompanyComplianceProfile(run.companyId);
        const preflightRequired = companyProfile?.preflightRequired ?? true;
        if (preflightRequired) {
          const { evaluateCompliance } = await import("./compliance-engine.js");

          let applicableRules: LaborRule[] = [];
          if (companyProfile?.jurisdictionId) {
            applicableRules = await storage.getApplicableRules(companyProfile.jurisdictionId, run.periodEnd, run.companyId);
          } else {
            const caJurisdiction = await storage.getJurisdictionByCode("CA");
            if (caJurisdiction) {
              applicableRules = await storage.getApplicableRules(caJurisdiction.id, run.periodEnd, run.companyId);
            }
          }

          const rulesInput = applicableRules.map(r => ({
            id: r.id,
            ruleType: r.ruleType,
            ruleValue: parseFloat(String(r.ruleValue)),
            ruleUnit: r.ruleUnit ?? null,
            overrideLevel: r.overrideLevel ?? null,
            wageOrderNumber: r.wageOrderNumber ?? null,
          }));

          // Load company sick leave account config for compliance validation
          const companySickAccounts = await storage.getAccrualAccounts(run.companyId);
          const sickAccount = companySickAccounts.find((a: any) => a.type === "sick" && a.isActive !== false);
          // sickLeaveMaxHours: employer's annual cap — must be >= CA minimum (40h)
          const sickLeaveMaxHours = sickAccount?.maxBalance != null
            ? parseFloat(String(sickAccount.maxBalance))
            : null;
          // sickLeaveAccrualDivisor: hours worked per 1 sick hour earned
          // Only meaningful when accrualFrequency is "hourly"; otherwise null (skip rate check)
          const sickLeaveAccrualDivisor = (sickAccount?.accrualFrequency === "hourly" && sickAccount?.accrualRate != null)
            ? (1 / parseFloat(String(sickAccount.accrualRate)))
            : null;

          const items = await storage.getPayrollItems(run.id);
          const allBlocks: any[] = [];

          for (const item of items) {
            const worker = await storage.getWorker(item.workerId);
            if (!worker) continue;
            const workerProfile = await storage.getWorkerComplianceProfile(worker.id);
            const entries = await storage.getTimeEntriesByDateRange(run.companyId, run.periodStart, run.periodEnd);
            const workerEntries = entries
              .filter(e => e.workerId === worker.id)
              .map(e => ({
                date: e.date,
                totalHours: parseFloat(String(e.totalHours ?? 0)),
                breakMinutes: e.breakMinutes ?? 0,
                scheduledHours: e.scheduledHours ? parseFloat(String(e.scheduledHours)) : undefined,
              }));

            const enforceFlags = {
              enforceDailyOt:       companyProfile?.enforceDailyOt    ?? true,
              enforceWeeklyOt:      companyProfile?.enforceWeeklyOt   ?? true,
              enforceSeventhDay:    companyProfile?.enforceSeventhDay  ?? true,
              enforceMealBreaks:    companyProfile?.enforceMealBreaks  ?? true,
              enforceRestBreaks:    companyProfile?.enforceRestBreaks  ?? true,
              enforceMinWage:       companyProfile?.enforceMinWage     ?? true,
              enforceFinalPaycheck: companyProfile?.enforceFinalPaycheck ?? true,
            };

            const ctx = {
              worker: {
                id: worker.id,
                payRate: parseFloat(String(worker.payRate ?? 0)),
                payType: worker.payType ?? "hourly",
                workerType: worker.workerType ?? "employee",
                status: worker.status ?? "active",
                terminationDate: worker.terminationDate ?? null,
                hireDate: worker.hireDate ?? null,
                exemptStatus: workerProfile?.exemptStatus ?? "nonexempt",
                abcTestA: workerProfile?.abcTestA ?? null,
                abcTestB: workerProfile?.abcTestB ?? null,
                abcTestC: workerProfile?.abcTestC ?? null,
              },
              entries: workerEntries,
              rules: rulesInput,
              periodStart: run.periodStart,
              periodEnd: run.periodEnd,
              grossPay: parseFloat(String(item.grossPay ?? 0)),
              enforceFlags,
              companyLocalMinWage: companyProfile?.localMinWage != null
                ? parseFloat(String(companyProfile.localMinWage))
                : null,
              workerMinWageOverride: workerProfile?.minWageOverride
                ? parseFloat(String(workerProfile.minWageOverride))
                : null,
              wageOrderNumber: companyProfile?.wageOrderNumber ?? null,
              sickLeaveMaxHours,
              sickLeaveAccrualDivisor,
              sickLeaveBalance: await (async () => {
                if (!sickAccount) return null;
                const balances = await storage.getAccrualBalances(worker.id);
                const sb = balances.find((b: any) => b.accrualAccountId === sickAccount.id);
                return sb?.balance != null ? parseFloat(String(sb.balance)) : null;
              })(),
            };

            const workerResults = evaluateCompliance(ctx);
            for (const r of workerResults) {
              // Write every evaluation result as an audit event
              try {
                await storage.createComplianceAuditEvent({
                  companyId: run.companyId,
                  payrollRunId: run.id,
                  workerId: worker.id,
                  ruleId: r.ruleId ?? null,
                  ruleType: r.ruleType,
                  entityType: "worker",
                  entityId: worker.id,
                  severity: r.severity,
                  message: r.message,
                  detail: r.detail,
                });
              } catch (_) { /* non-fatal */ }
              if (r.severity === "block") {
                allBlocks.push({ ...r, workerId: worker.id, workerName: `${worker.firstName} ${worker.lastName}` });
              }
            }
          }

          if (allBlocks.length > 0) {
            return res.status(422).json({
              message: `Payroll approval blocked: ${allBlocks.length} compliance violation${allBlocks.length !== 1 ? "s" : ""} must be resolved.`,
              blocks: allBlocks,
              canProceed: false,
            });
          }
        }
      } catch (preflightErr) {
        console.error("[compliance] Server-side preflight error:", preflightErr);
        return res.status(500).json({ message: "Compliance preflight evaluation failed. Payroll approval cannot proceed." });
      }
      // ────────────────────────────────────────────────────────────────────

      const prevStatus = run.status;
      const updated = await storage.updatePayrollRun(run.id, {
        approvedAt: new Date(),
        approvedBy: req.session.userId || null,
        status: "approved",
      });

      // Write audit log
      try {
        await storage.createPayrollPaymentAuditLog({
          companyId: run.companyId,
          payrollRunId: run.id,
          actorId: req.session.userId || null,
          event: "approved",
          previousStatus: prevStatus,
          newStatus: "approved",
          notes: "Payroll run approved by admin",
        });
      } catch (auditErr) {
        console.error("[PAYROLL] Audit log error on approve:", auditErr);
      }

      res.json(updated);
    } catch (error) {
      console.error("Approve payroll error:", error);
      res.status(500).json({ message: "Failed to approve payroll run" });
    }
  });

  // ── Shared readiness validator (used by /readiness and /submit-ach) ────────
  async function evaluatePayrollRunReadiness(run: Awaited<ReturnType<typeof storage.getPayrollRun>>) {
    if (!run) throw new Error("Run required");
    const items = await storage.getPayrollItems(run.id);
    const checks: Record<string, { ok: boolean; message: string; detail?: unknown }> = {};

    checks.status = {
      ok: run.status === "approved",
      message: run.status === "approved"
        ? "Run is approved and ready to submit"
        : `Run must be in 'approved' status (current: '${run.status}')`,
    };

    if (!run.fundingAccountId) {
      checks.fundingAccount = { ok: false, message: "No funding account linked to this run" };
    } else {
      const fundingAccounts = await storage.getFundingAccounts(run.companyId);
      const acct = fundingAccounts.find(a => a.id === run.fundingAccountId);
      const isActive = acct && (acct as Record<string, unknown>).active !== false;
      const allowsPayroll = acct && (acct as Record<string, unknown>).allowForPayroll !== false;
      const balance = acct ? Number((acct as Record<string, unknown>).currentBalance ?? (acct as Record<string, unknown>).openingBalance ?? 0) : 0;
      const totalNet = items.reduce((s, i) => s + parseFloat(i.netPay || "0"), 0);
      checks.fundingAccount = {
        ok: !!(acct && isActive && allowsPayroll && balance >= totalNet),
        message: !acct
          ? "Funding account not found"
          : !isActive
          ? "Funding account is inactive"
          : !allowsPayroll
          ? "Funding account is not enabled for payroll"
          : balance < totalNet
          ? `Insufficient balance: $${balance.toFixed(2)} available, $${totalNet.toFixed(2)} required`
          : "Funding account OK",
        detail: { balance, required: totalNet },
      };
    }

    // Per-worker pay-method integrity: every worker must have a paymentMethod set,
    // and direct-deposit workers must have an active pay method with non-empty routing+account values.
    const itemsMissing: string[] = [];
    const ddInvalid: { workerId: string; reason: string }[] = [];
    for (const item of items) {
      if (!item.paymentMethod) {
        itemsMissing.push(item.workerId);
        continue;
      }
      if (item.paymentMethod === "direct_deposit") {
        const methods = await storage.getPayMethods(item.workerId);
        const active = methods.find(m => m.isActive !== false && (m.isPrimary || methods.length === 1)) || methods.find(m => m.isActive !== false);
        if (!active) {
          ddInvalid.push({ workerId: item.workerId, reason: "no active pay method" });
          continue;
        }
        const routing = (active.routingNumber || "").trim();
        const account = (active.accountNumber || "").trim();
        // Reject masked or empty values (commonly stored as "****1234" when masked)
        if (!routing || routing.includes("*") || routing.length < 9) {
          ddInvalid.push({ workerId: item.workerId, reason: "missing or masked routing number" });
          continue;
        }
        if (!account || account.includes("*") || account.length < 4) {
          ddInvalid.push({ workerId: item.workerId, reason: "missing or masked account number" });
          continue;
        }
      }
    }
    const payMethodOk = itemsMissing.length === 0 && ddInvalid.length === 0;
    checks.workerPayMethods = {
      ok: payMethodOk,
      message: payMethodOk
        ? "All workers have a valid payment method"
        : `${itemsMissing.length} missing payment method, ${ddInvalid.length} direct-deposit account(s) invalid`,
      detail: { missing: itemsMissing, invalidDirectDeposit: ddInvalid },
    };

    checks.items = {
      ok: items.length > 0,
      message: items.length > 0 ? `${items.length} payroll items ready` : "No payroll items found",
    };

    const ready = Object.values(checks).every(c => c.ok);
    return { ready, checks, items };
  }

  // ── Payroll Run Readiness Check ────────────────────────────────────────────
  app.get("/api/payroll-runs/:id/readiness", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const user = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(user?.role) && user?.companyId && run.companyId !== user.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const { ready, checks } = await evaluatePayrollRunReadiness(run);
      res.json({ ready, checks });
    } catch (error) {
      console.error("Readiness check error:", error);
      res.status(500).json({ message: "Failed to check readiness" });
    }
  });

  // ── Submit ACH Batch ───────────────────────────────────────────────────────
  app.post("/api/payroll-runs/:id/submit-ach", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });

      // Tenant authorization: non-platform users may only submit runs in their own company
      const submitUser = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(submitUser?.role) && submitUser?.companyId && run.companyId !== submitUser.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }

      if (run.lockedAt || run.isLocked) return res.status(400).json({ message: "Payroll run is locked" });

      // ── Shared readiness gating: status, funding account, pay methods, items ─
      const readiness = await evaluatePayrollRunReadiness(run);
      if (!readiness.ready) {
        const failed = Object.entries(readiness.checks).filter(([, c]) => !c.ok).map(([k, c]) => ({ check: k, message: c.message, detail: c.detail }));
        return res.status(400).json({
          message: `Cannot submit ACH: ${failed.map(f => f.message).join("; ")}`,
          failedChecks: failed,
        });
      }
      const items = readiness.items;
      const prevStatus = run.status;
      const batchId = run.achBatchId || `ACH-${run.id.substring(0, 8).toUpperCase()}-${Date.now()}`;

      // Create ACH batch record if it doesn't exist
      const existingBatch = await storage.getAchBatch(run.id);
      if (!existingBatch) {
        const totalAmount = items.reduce((s, i) => s + parseFloat(i.netPay || "0"), 0);
        await storage.createAchBatch({
          payrollRunId: run.id,
          companyId: run.companyId,
          batchId,
          totalAmount: String(totalAmount),
          entryCount: items.length,
          status: "submitted",
          submittedAt: new Date(),
        });
      }

      const updated = await storage.updatePayrollRun(run.id, {
        achStatus: "submitted",
        achSubmittedAt: new Date(),
        achBatchId: batchId,
        status: "submitted",
      });

      // ── Auto-create payment records (idempotent) ───────────────────────────
      try {
        const existingRecords = await storage.getPayrollPaymentRecords(run.companyId, run.id);
        const existingWorkerIds = new Set(existingRecords.map(r => r.workerId));
        for (const item of items) {
          if (existingWorkerIds.has(item.workerId)) continue;
          await storage.createPayrollPaymentRecord({
            companyId: run.companyId,
            payrollRunId: run.id,
            payrollItemId: item.id,
            workerId: item.workerId,
            payDate: run.payDate || new Date().toISOString().split("T")[0],
            grossPayAmount: item.grossPay || "0",
            netPayAmount: item.netPay || "0",
            employeeTaxWithheld: item.deductions || "0",
            paymentMethodCode: item.paymentMethod || "check",
            fundingAccountId: run.fundingAccountId || null,
            achBatchId: batchId,
            status: "submitted",
            taxYear: run.payDate ? new Date(run.payDate + "T00:00:00").getFullYear() : new Date().getFullYear(),
            initiatedAt: new Date(),
          });
        }
      } catch (prErr) {
        console.error("[PAYROLL] Auto-create payment records error:", prErr);
      }

      // Write audit log
      try {
        await storage.createPayrollPaymentAuditLog({
          companyId: run.companyId,
          payrollRunId: run.id,
          actorId: req.session.userId || null,
          event: "submitted",
          previousStatus: prevStatus,
          newStatus: "submitted",
          notes: `ACH batch ${batchId} submitted`,
        });
      } catch (auditErr) {
        console.error("[PAYROLL] Audit log error on submit-ach:", auditErr);
      }

      // Send notification (best-effort)
      try {
        const { sendPayrollSubmittedNotification } = await import("./notifications.js");
        const company = await storage.getCompany(run.companyId);
        const adminUsers = (await storage.getUsers()).filter(u => u.companyId === run.companyId && (u.role === "admin" || u.role === "owner"));
        for (const admin of adminUsers) {
          if (admin.email) {
            await sendPayrollSubmittedNotification({
              toEmail: admin.email,
              adminName: admin.firstName ? `${admin.firstName} ${admin.lastName || ""}`.trim() : admin.username,
              companyName: company?.name || "Your Company",
              periodStart: run.periodStart || "",
              periodEnd: run.periodEnd || "",
              batchId,
              totalAmount: String(updated?.totalNetPay || 0),
            });
          }
        }
      } catch (notifErr) {
        console.error("[PAYROLL] Notification error on submit-ach:", notifErr);
      }

      // Per-worker submitted notifications (in-app + best-effort email)
      try {
        const { sendGenericNotificationEmail } = await import("./notifications.js");
        for (const item of items) {
          const worker = await storage.getWorker(item.workerId);
          if (!worker) continue;
          const amount = `$${Number(item.netPay || 0).toFixed(2)}`;
          const payDate = run.payDate || "your upcoming pay date";
          try {
            await storage.createNotification({
              companyId: run.companyId,
              userId: null,
              workerId: worker.id,
              customerId: null,
              type: "payment_submitted",
              title: `Payment of ${amount} submitted`,
              message: `Your payment of ${amount} for pay date ${payDate} has been submitted and is being processed.`,
              actionUrl: `/portal/paystubs`,
              isRead: false,
              readAt: null,
            });
          } catch (nErr) {
            console.error("[PAYROLL] Worker submitted in-app notification error:", nErr);
          }
          if (worker.email) {
            try {
              await sendGenericNotificationEmail({
                recipientName: `${worker.firstName || ""} ${worker.lastName || ""}`.trim() || "Worker",
                email: worker.email,
                title: `Payment submitted`,
                body: `Your payment of ${amount} for pay date ${payDate} has been submitted and is being processed. You'll be notified again once it's confirmed.`,
              });
            } catch (eErr) {
              console.error("[PAYROLL] Worker submitted email error:", eErr);
            }
          }
        }
      } catch (workerNotifErr) {
        console.error("[PAYROLL] Worker submitted notification error:", workerNotifErr);
      }

      res.json(updated);
    } catch (error) {
      console.error("Submit ACH error:", error);
      res.status(500).json({ message: "Failed to submit ACH batch" });
    }
  });

  // ── Void Payroll Run ───────────────────────────────────────────────────────
  app.post("/api/payroll-runs/:id/void", requireAuth, requireRole("admin"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const voidUser = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(voidUser?.role) && voidUser?.companyId && run.companyId !== voidUser.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      // State machine: only submitted or failed runs can be voided
      if (run.status !== "submitted" && run.status !== "failed") {
        return res.status(400).json({ message: `Cannot void a payroll run with status "${run.status}". Only submitted or failed runs can be voided.` });
      }
      const { reason } = req.body || {};
      const prevStatus = run.status;

      // Mark all payment records as voided + per-record audit entry
      try {
        const paymentRecords = await storage.getPayrollPaymentRecords(run.companyId, run.id);
        for (const pr of paymentRecords) {
          if (pr.status !== "voided" && pr.status !== "reversed") {
            const prevPrStatus = pr.status;
            await storage.updatePayrollPaymentRecord(pr.id, {
              status: "voided",
              voidedAt: new Date(),
            });
            try {
              await storage.createPayrollPaymentAuditLog({
                companyId: pr.companyId,
                payrollRunId: pr.payrollRunId,
                payrollPaymentRecordId: pr.id,
                actorId: req.session.userId || null,
                event: "voided",
                previousStatus: prevPrStatus,
                newStatus: "voided",
                notes: reason || "Voided as part of run void",
              });
            } catch (auditErr) {
              console.error("[PAYROLL] Per-record void audit error:", auditErr);
            }
          }
        }
      } catch (prErr) {
        console.error("[PAYROLL] Error voiding payment records:", prErr);
      }

      // Update ACH batch
      try {
        const batch = await storage.getAchBatch(run.id);
        if (batch) {
          await storage.updateAchBatch(batch.id, { status: "voided" });
        }
      } catch (batchErr) {
        console.error("[PAYROLL] Error voiding ACH batch:", batchErr);
      }

      const updated = await storage.updatePayrollRun(run.id, {
        status: "voided",
        voidedAt: new Date(),
        voidedBy: req.session.userId || null,
        failureReason: reason || null,
      });

      await storage.createPayrollPaymentAuditLog({
        companyId: run.companyId,
        payrollRunId: run.id,
        actorId: req.session.userId || null,
        event: "voided",
        previousStatus: prevStatus,
        newStatus: "voided",
        notes: reason || "Voided by admin",
      });

      res.json(updated);
    } catch (error) {
      console.error("Void payroll error:", error);
      res.status(500).json({ message: "Failed to void payroll run" });
    }
  });

  // ── Reverse Payroll Run ─────────────────────────────────────────────────────
  app.post("/api/payroll-runs/:id/reverse", requireAuth, requireRole("admin"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const revUser = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(revUser?.role) && revUser?.companyId && run.companyId !== revUser.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      // State machine: only paid runs can be reversed
      if (run.status !== "paid") {
        return res.status(400).json({ message: `Cannot reverse a payroll run with status "${run.status}". Only paid runs can be reversed.` });
      }
      const { reason } = req.body || {};
      const prevStatus = run.status;

      // Mark payment records as reversed + per-record audit entry
      try {
        const paymentRecords = await storage.getPayrollPaymentRecords(run.companyId, run.id);
        for (const pr of paymentRecords) {
          if (pr.status !== "reversed" && pr.status !== "voided") {
            const prevPrStatus = pr.status;
            await storage.updatePayrollPaymentRecord(pr.id, {
              status: "reversed",
              reversedAt: new Date(),
            });
            try {
              await storage.createPayrollPaymentAuditLog({
                companyId: pr.companyId,
                payrollRunId: pr.payrollRunId,
                payrollPaymentRecordId: pr.id,
                actorId: req.session.userId || null,
                event: "reversed",
                previousStatus: prevPrStatus,
                newStatus: "reversed",
                notes: reason || "Reversed as part of run reverse",
              });
            } catch (auditErr) {
              console.error("[PAYROLL] Per-record reverse audit error:", auditErr);
            }
          }
        }
      } catch (prErr) {
        console.error("[PAYROLL] Error reversing payment records:", prErr);
      }

      const updated = await storage.updatePayrollRun(run.id, {
        status: "reversed",
        reversedAt: new Date(),
        reversedBy: req.session.userId || null,
        failureReason: reason || null,
      });

      await storage.createPayrollPaymentAuditLog({
        companyId: run.companyId,
        payrollRunId: run.id,
        actorId: req.session.userId || null,
        event: "reversed",
        previousStatus: prevStatus,
        newStatus: "reversed",
        notes: reason || "Reversed by admin",
      });

      // Send failure notification (best-effort)
      try {
        const { sendPaymentFailedNotification } = await import("./notifications.js");
        const company = await storage.getCompany(run.companyId);
        const adminUsers = (await storage.getUsers()).filter(u => u.companyId === run.companyId && (u.role === "admin" || u.role === "owner"));
        for (const admin of adminUsers) {
          if (admin.email) {
            await sendPaymentFailedNotification({
              toEmail: admin.email,
              adminName: admin.firstName ? `${admin.firstName} ${admin.lastName || ""}`.trim() : admin.username,
              companyName: company?.name || "Your Company",
              periodStart: run.periodStart || "",
              periodEnd: run.periodEnd || "",
              reason: reason || "Payment reversed",
              runId: run.id,
            });
          }
        }
      } catch (notifErr) {
        console.error("[PAYROLL] Notification error on reverse:", notifErr);
      }

      res.json(updated);
    } catch (error) {
      console.error("Reverse payroll error:", error);
      res.status(500).json({ message: "Failed to reverse payroll run" });
    }
  });

  // ── Reconcile payment record ────────────────────────────────────────────────
  app.post("/api/payroll-payment-records/:id/reconcile", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const { notes } = req.body || {};
      const records = await storage.getPayrollPaymentRecords(user?.companyId || "");
      const record = records.find(r => r.id === req.params.id);
      if (!record) return res.status(404).json({ message: "Payment record not found" });
      if (!isPlatformUser(user?.role) && user?.companyId && record.companyId !== user.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const updated = await storage.updatePayrollPaymentRecord(record.id, {
        reconciledAt: new Date(),
        status: "cleared",
      });

      await storage.createPayrollPaymentAuditLog({
        companyId: record.companyId,
        payrollRunId: record.payrollRunId,
        payrollPaymentRecordId: record.id,
        actorId: req.session.userId || null,
        event: "reconciled",
        previousStatus: record.status,
        newStatus: "cleared",
        notes: notes || "Manually reconciled",
      });

      res.json(updated);
    } catch (error) {
      console.error("Reconcile error:", error);
      res.status(500).json({ message: "Failed to reconcile payment record" });
    }
  });

  // ── Run-level Reconcile ────────────────────────────────────────────────────
  app.post("/api/payroll-runs/:id/reconcile", requireAuth, requireRole("admin"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const user = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(user?.role) && user?.companyId && run.companyId !== user.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const { recordIds, notes } = req.body || {};
      const allRecords = await storage.getPayrollPaymentRecords(run.companyId, run.id);
      const toReconcile = recordIds
        ? allRecords.filter(r => recordIds.includes(r.id))
        : allRecords.filter(r => r.status === "paid" || r.status === "cleared");
      let reconciledCount = 0;
      for (const record of toReconcile) {
        if (record.reconciledAt) continue;
        await storage.updatePayrollPaymentRecord(record.id, {
          reconciledAt: new Date(),
          status: "cleared",
        });
        await storage.createPayrollPaymentAuditLog({
          companyId: record.companyId,
          payrollRunId: record.payrollRunId,
          payrollPaymentRecordId: record.id,
          actorId: req.session.userId || null,
          event: "reconciled",
          previousStatus: record.status,
          newStatus: "cleared",
          notes: notes || "Bulk reconciled by admin",
        });
        reconciledCount++;
      }
      res.json({ reconciled: reconciledCount, total: toReconcile.length });
    } catch (error) {
      console.error("Run-level reconcile error:", error);
      res.status(500).json({ message: "Failed to reconcile payroll run" });
    }
  });

  // ── Reconciliation Summary ─────────────────────────────────────────────────
  app.get("/api/payroll-runs/:id/reconciliation-summary", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const user = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(user?.role) && user?.companyId && run.companyId !== user.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const records = await storage.getPayrollPaymentRecords(run.companyId, run.id);
      const items = await storage.getPayrollItems(run.id);
      const sumOf = (rs: typeof records) => rs.reduce((s, r) => s + parseFloat(r.netPayAmount || "0"), 0);
      const byStatus = (status: string) => records.filter(r => r.status === status);

      const expectedCount = items.length;
      const expectedAmount = items.reduce((s, i) => s + parseFloat(i.netPay || "0"), 0);

      const submitted = byStatus("submitted");
      const processing = byStatus("processing");
      const paid = records.filter(r => r.status === "paid" || r.status === "cleared");
      const failed = byStatus("failed");
      const voided = byStatus("voided");
      const reversed = byStatus("reversed");
      const reconciled = records.filter(r => !!r.reconciledAt);
      const pending = records.filter(r => !r.reconciledAt && r.status !== "voided" && r.status !== "reversed" && r.status !== "failed");

      const paidAmount = sumOf(paid);
      const reconciledAmount = sumOf(reconciled);
      const failedAmount = sumOf(failed);

      // Discrepancies: expected vs paid (count and amount)
      const discrepancies = {
        countDelta: expectedCount - paid.length,
        amountDelta: Number((expectedAmount - paidAmount).toFixed(2)),
        unmatchedRecordIds: records.filter(r => r.status === "failed" || (r.status === "paid" && !r.reconciledAt)).map(r => r.id),
      };

      res.json({
        runId: run.id,
        runStatus: run.status,
        expected: { count: expectedCount, amount: Number(expectedAmount.toFixed(2)) },
        submitted: { count: submitted.length, amount: Number(sumOf(submitted).toFixed(2)) },
        processing: { count: processing.length, amount: Number(sumOf(processing).toFixed(2)) },
        paid: { count: paid.length, amount: Number(paidAmount.toFixed(2)) },
        failed: { count: failed.length, amount: Number(failedAmount.toFixed(2)) },
        voided: { count: voided.length, amount: Number(sumOf(voided).toFixed(2)) },
        reversed: { count: reversed.length, amount: Number(sumOf(reversed).toFixed(2)) },
        reconciled: { count: reconciled.length, amount: Number(reconciledAmount.toFixed(2)) },
        pending: { count: pending.length, amount: Number(sumOf(pending).toFixed(2)) },
        discrepancies,
      });
    } catch (error) {
      res.status(500).json({ message: "Failed to get reconciliation summary" });
    }
  });

  // ── Get payment records for a payroll run ──────────────────────────────────
  app.get("/api/payroll-runs/:id/payment-records", requireAuth, requireRole("admin", "manager", "worker"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const user = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(user?.role) && user?.companyId && run.companyId !== user.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const records = await storage.getPayrollPaymentRecords(run.companyId, run.id);
      // Workers can only see their own payment record
      if (user?.role === "worker") {
        const worker = (await storage.getWorkers(run.companyId)).find(w => w.userId === user.id);
        if (!worker) return res.json([]);
        return res.json(records.filter(r => r.workerId === worker.id));
      }
      res.json(records);
    } catch (error) {
      res.status(500).json({ message: "Failed to get payment records" });
    }
  });

  // ── Get audit logs for a payroll run ───────────────────────────────────────
  app.get(["/api/payroll-runs/:id/audit-logs", "/api/payroll-runs/:id/audit-log"], requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const user = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(user?.role) && user?.companyId && run.companyId !== user.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const logs = await storage.listPayrollPaymentAuditLogs(run.id);
      res.json(logs);
    } catch (error) {
      res.status(500).json({ message: "Failed to get audit logs" });
    }
  });

  // ── Mark payment record as paid (manual reconcile) ─────────────────────────
  app.post("/api/payroll-payment-records/:id/mark-paid", requireAuth, requireRole("admin"), requireActiveSubscription, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const { notes } = req.body || {};
      const records = await storage.getPayrollPaymentRecords(user?.companyId || "");
      const record = records.find(r => r.id === req.params.id);
      if (!record) return res.status(404).json({ message: "Payment record not found" });
      if (!isPlatformUser(user?.role) && user?.companyId && record.companyId !== user.companyId) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const updated = await storage.updatePayrollPaymentRecord(record.id, {
        status: "paid",
        paidAt: new Date(),
      });

      await storage.createPayrollPaymentAuditLog({
        companyId: record.companyId,
        payrollRunId: record.payrollRunId,
        payrollPaymentRecordId: record.id,
        actorId: req.session.userId || null,
        event: "paid",
        previousStatus: record.status,
        newStatus: "paid",
        notes: notes || "Manually marked as paid",
      });

      // Recompute run status — if all records are paid, mark run as paid
      try {
        const allRecords = await storage.getPayrollPaymentRecords(record.companyId!, record.payrollRunId!);
        const allPaid = allRecords.length > 0 && allRecords.every(r => r.status === "paid" || r.status === "cleared");
        if (allPaid) {
          const run = await storage.getPayrollRun(record.payrollRunId!);
          if (run && run.status === "submitted" || run?.status === "processing") {
            await storage.updatePayrollRun(record.payrollRunId!, {
              status: "paid",
              achStatus: "settled",
              achSettledAt: new Date(),
            });
            await storage.createPayrollPaymentAuditLog({
              companyId: record.companyId,
              payrollRunId: record.payrollRunId,
              actorId: req.session.userId || null,
              event: "paid",
              previousStatus: run.status,
              newStatus: "paid",
              notes: "All payment records marked paid — run auto-completed",
            });
          }
        }
      } catch (recomputeErr) {
        console.error("[PAYROLL] Run status recompute error:", recomputeErr);
      }

      res.json(updated);
    } catch (error) {
      console.error("Mark paid error:", error);
      res.status(500).json({ message: "Failed to mark payment as paid" });
    }
  });

  // ── Lock Payroll Run ───────────────────────────────────────────────────────
  app.post("/api/payroll-runs/:id/lock", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const lockUser = await storage.getUser(req.session.userId!);
      if (!isPlatformUser(lockUser?.role) && lockUser?.companyId && run.companyId !== lockUser.companyId) {
        return res.status(403).json({ message: "Forbidden: payroll run belongs to a different company" });
      }
      if (run.status === "draft") return res.status(400).json({ message: "Cannot lock a draft payroll run. Process it first." });
      if (!run.approvedAt) return res.status(400).json({ message: "Payroll run must be approved before locking" });
      if (run.lockedAt || run.isLocked) return res.status(400).json({ message: "Payroll run is already locked" });
      if (run.useDirectDeposit !== false) {
        const achSt = run.achStatus;
        if (achSt !== "submitted" && achSt !== "settled") {
          return res.status(400).json({ message: "Cannot lock: ACH batch must be submitted before locking. Submit the ACH batch or disable direct deposit." });
        }
      }
      const updated = await storage.updatePayrollRun(run.id, {
        lockedAt: new Date(),
        lockedBy: req.session.userId || null,
      });
      res.json(updated);
    } catch (error) {
      console.error("Lock payroll error:", error);
      res.status(500).json({ message: "Failed to lock payroll run" });
    }
  });

  // ── Bulk Lock Payroll Runs ─────────────────────────────────────────────────
  // Locks every eligible run for a company: must be processed, approved, not
  // already locked, and (if useDirectDeposit) have ACH submitted/settled.
  app.post("/api/payroll-runs/bulk-lock", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const requestUser = await storage.getUser(req.session.userId!);
      const { companyId } = req.body;
      const isPlatform = isPlatformUser(requestUser?.role);
      const effectiveCompanyId = (!isPlatform && requestUser?.companyId)
        ? requestUser.companyId
        : companyId || undefined;
      // Tenant users must always have a companyId; platform users may omit it to lock all companies
      if (!isPlatform && !effectiveCompanyId) return res.status(400).json({ message: "companyId required" });

      const allRuns = await storage.getPayrollRuns(effectiveCompanyId);
      const locked: string[] = [];
      const skipped: { id: string; reason: string }[] = [];

      for (const run of allRuns) {
        if (run.lockedAt || run.isLocked) { skipped.push({ id: run.id, reason: "already locked" }); continue; }
        if (run.status === "draft") { skipped.push({ id: run.id, reason: "still a draft — process it first" }); continue; }
        if (!run.approvedAt) { skipped.push({ id: run.id, reason: "not yet approved" }); continue; }
        // Only gate on ACH if direct deposit is explicitly enabled (true).
        // Null/undefined means not configured — treat as check/manual payment.
        if (run.useDirectDeposit === true) {
          const achSt = run.achStatus;
          if (achSt !== "submitted" && achSt !== "settled") {
            skipped.push({ id: run.id, reason: "ACH not yet submitted" }); continue;
          }
        }
        await storage.updatePayrollRun(run.id, { lockedAt: new Date(), lockedBy: req.session.userId || null });
        locked.push(run.id);
      }

      res.json({ locked: locked.length, skipped: skipped.length, skippedDetails: skipped });
    } catch (error) {
      console.error("Bulk lock payroll error:", error);
      res.status(500).json({ message: "Bulk lock failed" });
    }
  });

  // ── NACHA ACH File Generation ─────────────────────────────────────────────
  app.get("/api/payroll-runs/:id/nacha", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      if (!run.useDirectDeposit) return res.status(400).json({ message: "Direct deposit is disabled for this payroll run" });
      if (run.status !== "processed" && run.status !== "paid") return res.status(400).json({ message: "Payroll run must be processed before generating ACH file" });

      const company = await storage.getCompany(run.companyId);
      if (!company) return res.status(404).json({ message: "Company not found" });

      const { remittanceSources } = await import("../shared/schema.js");
      const sources = await db.select().from(remittanceSources).where(eq(remittanceSources.companyId, run.companyId));
      const source = sources.find(s => (s.type === "ach" || s.type === "direct_deposit") && s.routingNumber) || sources.find(s => s.routingNumber);
      if (!source || !source.routingNumber || !source.accountNumber) {
        return res.status(400).json({ message: "No ACH remittance source configured for this company. Please add a remittance source with a routing and account number." });
      }

      const items = await storage.getPayrollItems(run.id);
      const { payMethods } = await import("../shared/schema.js");

      type PayMethodRow = { id: string; workerId: string; methodType: string; routingNumber: string | null; accountNumber: string | null; accountType: string | null; isPrimary: boolean | null; platform: string | null };
      const allPayMethods = await db.select().from(payMethods) as PayMethodRow[];

      const workers = await storage.getWorkers(run.companyId);
      const workerMap: Record<string, typeof workers[0]> = {};
      for (const w of workers) workerMap[w.id] = w;

      const pr = (s: string, len: number) => s.substring(0, len).padEnd(len, " ");
      const pl = (s: string, len: number) => s.substring(0, len).padStart(len, "0");
      const nachaDate = (d: Date) => {
        const yy = d.getFullYear().toString().slice(-2);
        const mm = (d.getMonth() + 1).toString().padStart(2, "0");
        const dd = d.getDate().toString().padStart(2, "0");
        return `${yy}${mm}${dd}`;
      };

      const effectiveDate = run.payDate ? new Date(run.payDate + "T12:00:00") : new Date();
      const now = new Date();
      const fileDate = nachaDate(now);
      const fileTime = now.getHours().toString().padStart(2, "0") + now.getMinutes().toString().padStart(2, "0");
      const effDate = nachaDate(effectiveDate);

      const odfiRouting = (source.routingNumber || "").replace(/\D/g, "").substring(0, 9);
      const odfi8 = odfiRouting.substring(0, 8);
      const companyId10 = "1" + ((company.ein || "").replace(/\D/g, "").substring(0, 9)).padStart(9, "0");
      const companyName16 = pr(company.name || "", 16);
      const immDest = source.immediateDest || (" " + odfiRouting);
      const immDestName = pr(source.immediateDestName || source.institution || "BANK", 23);
      const immOrigin = source.immediateOrigin || companyId10;
      const immOriginName = pr(source.immediateOriginName || company.name || "", 23);

      const fileHeader =
        "1" +
        "01" +
        pl(immDest.padStart(10, " "), 10) +
        pl(immOrigin, 10) +
        fileDate +
        fileTime +
        "A" +
        "094" +
        "10" +
        "1" +
        immDestName +
        immOriginName +
        "        ";

      const entries: string[] = [];
      let entryHash = BigInt(0);
      let totalCreditCents = BigInt(0);
      let seqNum = 1;

      for (const item of items) {
        const worker = workerMap[item.workerId];
        if (!worker) continue;
        const netPay = parseFloat(item.netPay || "0");
        if (netPay <= 0) continue;

        const pm = allPayMethods.find(m =>
          m.workerId === item.workerId &&
          m.methodType === "direct_deposit" &&
          !m.platform &&
          m.routingNumber &&
          m.accountNumber
        ) || allPayMethods.find(m =>
          m.workerId === item.workerId &&
          m.methodType === "direct_deposit" &&
          m.routingNumber &&
          m.accountNumber
        );
        if (!pm || !pm.routingNumber || !pm.accountNumber) continue;

        const rdfiRouting = pm.routingNumber.replace(/\D/g, "").substring(0, 9);
        const rdfi8 = rdfiRouting.substring(0, 8);
        const checkDigit = rdfiRouting.substring(8, 9) || "0";
        const txnCode = (pm.accountType === "savings") ? "32" : "22";
        const cents = Math.round(netPay * 100);
        const dfiAccount = pr(pm.accountNumber.replace(/\D/g, ""), 17);
        const amount10 = pl(cents.toString(), 10);
        const workerName = pr(`${worker.firstName || ""} ${worker.lastName || ""}`.trim(), 22);
        const indivId = pr(worker.id.substring(0, 15), 15);
        const traceNum = odfi8 + pl(seqNum.toString(), 7);

        entryHash += BigInt(rdfi8);
        totalCreditCents += BigInt(cents);

        entries.push(
          "6" +
          txnCode +
          rdfi8 +
          checkDigit +
          dfiAccount +
          amount10 +
          indivId +
          workerName +
          "  " +
          "0" +
          traceNum
        );
        seqNum++;
      }

      if (entries.length === 0) {
        return res.status(400).json({ message: "No employees with direct deposit banking information found in this payroll run." });
      }

      const entryCount = entries.length;
      const hashStr = pl((entryHash % BigInt(10000000000)).toString(), 10);
      const totalCreditStr = pl(totalCreditCents.toString(), 12);
      const batchNum7 = "0000001";

      const batchHeader =
        "5" +
        "220" +
        companyName16 +
        "                    " +
        companyId10 +
        "PPD" +
        pr("PAYROLL", 10) +
        "      " +
        effDate +
        "   " +
        "1" +
        odfi8 +
        batchNum7;

      const batchControl =
        "8" +
        "220" +
        pl(entryCount.toString(), 6) +
        hashStr +
        "000000000000" +
        totalCreditStr +
        companyId10 +
        "                   " +
        "      " +
        odfi8 +
        batchNum7;

      const allRecords = [fileHeader, batchHeader, ...entries, batchControl];
      const totalRecords = allRecords.length + 1;
      const blockCount = Math.ceil((totalRecords) / 10);
      const paddingNeeded = blockCount * 10 - totalRecords;

      const fileControl =
        "9" +
        "000001" +
        pl(blockCount.toString(), 6) +
        pl(entryCount.toString(), 8) +
        hashStr +
        "000000000000" +
        totalCreditStr +
        " ".repeat(39);

      allRecords.push(fileControl);
      for (let i = 0; i < paddingNeeded; i++) {
        allRecords.push("9".repeat(94));
      }

      const nachaContent = allRecords.join("\r\n") + "\r\n";
      const fileName = `ACH_${company.name.replace(/\s+/g, "_")}_${run.periodEnd}.ach`;

      res.setHeader("Content-Type", "text/plain");
      res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
      res.send(nachaContent);
    } catch (error) {
      console.error("NACHA generation error:", error);
      res.status(500).json({ message: "Failed to generate ACH file" });
    }
  });

  // ── Stripe Treasury Routes ─────────────────────────────────────────────────

  app.get("/api/treasury/status", requireAuth, requireRole("admin"), requireFeature("tenant.finance.treasury"), async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      if (!user?.companyId) return res.status(400).json({ message: "No company associated with this account" });
      const company = await storage.getCompany(user.companyId);
      if (!company) return res.status(404).json({ message: "Company not found" });

      const { getOrCreateFinancialAccount } = await import("./treasury.js");

      if (!company.stripeFinancialAccountId) {
        return res.json({ connected: false, company: { id: company.id, name: company.name } });
      }

      const { getFinancialAccount } = await import("./treasury.js");
      const fa = await getFinancialAccount(company.stripeFinancialAccountId);
      res.json({ connected: true, financialAccount: fa, company: { id: company.id, name: company.name } });
    } catch (error: any) {
      console.error("Treasury status error:", error);
      res.status(500).json({ message: error.message || "Failed to get treasury status" });
    }
  });

  app.post("/api/treasury/setup", requireAuth, requireRole("admin", "platform_super_admin", "platform_admin"), async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      // Platform admins may pass a companyId in the request body; company admins use their own
      const companyId = isPlatformUser(user?.role) ? (req.body?.companyId || user?.companyId) : user?.companyId;
      if (!companyId) {
        return res.status(400).json({
          message: "No company associated with this account. Platform admins must pass a companyId in the request body."
        });
      }
      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ message: "Company not found" });

      const { getOrCreateFinancialAccount } = await import("./treasury.js");
      const fa = await getOrCreateFinancialAccount(company);

      if (fa.id !== company.stripeFinancialAccountId) {
        await storage.updateCompany(company.id, { stripeFinancialAccountId: fa.id } as any);
      }

      // Ensure the treasury feature is enabled for this company after successful setup
      await db.execute(sql`
        INSERT INTO feature_overrides (id, feature_key, company_id, enabled, updated_at)
        VALUES (gen_random_uuid(), 'tenant.finance.treasury', ${companyId}, TRUE, NOW())
        ON CONFLICT (feature_key, company_id)
        DO UPDATE SET enabled = TRUE, updated_at = NOW()
      `);

      res.json({ success: true, financialAccount: fa });
    } catch (error: any) {
      console.error("Treasury setup error:", error);
      // Provide a user-friendly message for common Stripe errors
      let msg = error.message || "Failed to set up Stripe Treasury";
      if (error.type === "StripePermissionError" || error.code === "treasury_not_enabled") {
        msg = "Stripe Treasury is not enabled on your Stripe account. Please enable it in your Stripe Dashboard under Treasury, then try again.";
      } else if (error.type === "StripeAuthenticationError") {
        msg = "Stripe authentication failed. Please check that the Stripe integration is properly configured.";
      } else if (error.raw?.message) {
        msg = error.raw.message;
      }
      res.status(500).json({ message: msg });
    }
  });

  app.get("/api/treasury/transactions", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      if (!user?.companyId) return res.status(400).json({ message: "No company" });
      const payrollRunId = req.query.payrollRunId as string | undefined;
      const transactions = await storage.getTreasuryOutboundPayments(user.companyId, payrollRunId);
      res.json(transactions);
    } catch (error: any) {
      console.error("Treasury transactions error:", error);
      res.status(500).json({ message: "Failed to fetch treasury transactions" });
    }
  });

  app.post("/api/treasury/sync", requireAuth, requireRole("admin"), async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      if (!user?.companyId) return res.status(400).json({ message: "No company" });
      const company = await storage.getCompany(user.companyId);
      if (!company?.stripeFinancialAccountId) return res.status(400).json({ message: "Treasury not set up" });

      const { listOutboundPayments } = await import("./treasury.js");
      const stripePayments = await listOutboundPayments(company.stripeFinancialAccountId);

      let updated = 0;
      for (const sp of stripePayments) {
        const existing = await storage.getTreasuryOutboundPaymentByStripeId(sp.id);
        if (existing) {
          const newStatus = sp.status === "posted" ? "completed" : sp.status === "failed" ? "failed" : sp.status === "returned" ? "returned" : sp.status === "canceled" ? "canceled" : existing.status;
          if (newStatus !== existing.status) {
            await storage.updateTreasuryOutboundPayment(existing.id, {
              status: newStatus,
              stripeRawStatus: sp.status,
              errorMessage: sp.returned_details?.reason || null,
            } as any);
            updated++;
          }
        }
      }

      res.json({ synced: stripePayments.length, updated });
    } catch (error: any) {
      console.error("Treasury sync error:", error);
      res.status(500).json({ message: error.message || "Failed to sync treasury" });
    }
  });

  app.post("/api/payroll-runs/:id/disburse-stripe", requireAuth, requireRole("admin"), requireActiveSubscription, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      if (!user?.companyId) return res.status(400).json({ message: "No company" });
      const company = await storage.getCompany(user.companyId);
      if (!company) return res.status(404).json({ message: "Company not found" });
      if (!company.stripeFinancialAccountId) return res.status(400).json({ message: "Stripe Treasury is not set up. Go to Treasury settings to enable it." });

      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      if (run.companyId !== user.companyId) return res.status(403).json({ message: "Not authorized" });
      if (run.status !== "processed" && run.status !== "approved") return res.status(400).json({ message: "Payroll run must be processed and approved before disbursing" });
      if (!run.approvedAt) return res.status(400).json({ message: "Payroll run must be approved before disbursing" });
      if (run.lockedAt || run.isLocked) return res.status(400).json({ message: "Payroll run is locked" });

      const items = await storage.getPayrollItems(run.id);
      if (items.length === 0) return res.status(400).json({ message: "No payroll items found" });

      const allPayMethods = await storage.getPayMethods();
      const payMethodMap = new Map(allPayMethods.map(pm => [pm.workerId, pm]));

      const { validatePayrollReadiness, getFinancialAccount, createOutboundPayment } = await import("./treasury.js");

      const fa = await getFinancialAccount(company.stripeFinancialAccountId);
      const balance = fa.balance;

      const totalNetPay = items.reduce((sum, item) => {
        if ((item.paymentMethod || "check") !== "direct_deposit" && (item.paymentMethod || "check") !== "ach") return sum;
        return sum + parseFloat(item.netPay || "0");
      }, 0);

      if (balance && balance.cash < totalNetPay) {
        return res.status(400).json({
          message: `Insufficient balance. Financial account has $${balance.cash.toFixed(2)} but payroll requires $${totalNetPay.toFixed(2)}.`,
          balance: balance.cash,
          required: totalNetPay,
        });
      }

      const directDepositItems = items.filter(item => {
        const pm = payMethodMap.get(item.workerId);
        return pm?.methodType === "direct_deposit";
      });

      const validationInput = directDepositItems.map(item => {
        const pm = payMethodMap.get(item.workerId);
        return { worker: { firstName: "", lastName: item.workerName || item.workerId, id: item.workerId } as any, payMethod: pm, netPay: parseFloat(item.netPay || "0") };
      });

      const { valid, errors } = validatePayrollReadiness(validationInput);
      if (!valid) return res.status(400).json({ message: "Payroll validation failed", errors });

      const results: { workerId: string; workerName: string; amount: number; status: string; error?: string }[] = [];
      let successCount = 0;
      let failCount = 0;

      for (const item of directDepositItems) {
        const pm = payMethodMap.get(item.workerId)!;
        const netPay = parseFloat(item.netPay || "0");
        if (netPay <= 0) continue;
        const amountCents = Math.round(netPay * 100);
        const workerName = item.workerName || item.workerId;

        try {
          const payment = await createOutboundPayment({
            financialAccountId: company.stripeFinancialAccountId!,
            routingNumber: pm.routingNumber!,
            accountNumber: pm.accountNumber!,
            accountType: (pm.accountType || "checking") as "checking" | "savings",
            recipientName: workerName,
            amountCents,
            memo: `PAYROLL ${run.id.substring(0, 8).toUpperCase()}`,
            idempotencyKey: `payroll-${run.id}-${item.workerId}`,
          });

          await storage.createTreasuryOutboundPayment({
            companyId: company.id,
            payrollRunId: run.id,
            workerId: item.workerId,
            stripeOutboundPaymentId: payment.stripeOutboundPaymentId,
            stripeFinancialAccountId: company.stripeFinancialAccountId,
            amount: amountCents,
            currency: "usd",
            status: payment.status === "posted" ? "completed" : "pending",
            recipientName: workerName,
            routingNumber: pm.routingNumber,
            accountNumber: pm.accountNumber ? `****${pm.accountNumber.slice(-4)}` : null,
            memo: `PAYROLL ${run.id.substring(0, 8).toUpperCase()}`,
            stripeRawStatus: payment.status,
          });

          results.push({ workerId: item.workerId, workerName, amount: netPay, status: payment.status });
          successCount++;
        } catch (err: any) {
          console.error(`[TREASURY] Failed payment for ${workerName}:`, err);
          await storage.createTreasuryOutboundPayment({
            companyId: company.id,
            payrollRunId: run.id,
            workerId: item.workerId,
            stripeOutboundPaymentId: null,
            stripeFinancialAccountId: company.stripeFinancialAccountId,
            amount: amountCents,
            currency: "usd",
            status: "failed",
            recipientName: workerName,
            routingNumber: pm.routingNumber,
            accountNumber: pm.accountNumber ? `****${pm.accountNumber.slice(-4)}` : null,
            memo: `PAYROLL ${run.id.substring(0, 8).toUpperCase()}`,
            errorMessage: err.message,
            stripeRawStatus: "failed",
          });
          results.push({ workerId: item.workerId, workerName, amount: netPay, status: "failed", error: err.message });
          failCount++;
        }
      }

      if (successCount > 0) {
        await storage.updatePayrollRun(run.id, {
          achStatus: "submitted",
          achSubmittedAt: new Date(),
          achBatchId: `TRS-${run.id.substring(0, 8).toUpperCase()}-${Date.now()}`,
          status: failCount === 0 ? "paid" : run.status,
        });
      }

      res.json({
        success: failCount === 0,
        successCount,
        failCount,
        results,
        message: failCount === 0
          ? `Successfully initiated ${successCount} direct deposit(s) via Stripe Treasury`
          : `${successCount} payments initiated, ${failCount} failed. Check transaction details.`,
      });
    } catch (error: any) {
      console.error("Treasury disburse error:", error);
      res.status(500).json({ message: error.message || "Failed to disburse payroll via Stripe Treasury" });
    }
  });

  // ── Per-agency liability breakdown ────────────────────────────────────────
  app.get("/api/payroll-runs/:id/agency-liabilities", requireAuth, requireRole("admin", "manager"), requireActiveSubscription, async (req, res) => {
    try {
      const run = await storage.getPayrollRun(req.params.id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      const items = await storage.getPayrollItems(run.id);
      const allDeductions = await storage.getTaxesDeductions(run.companyId);
      const allAgencies = await storage.getRemittanceAgencies(run.companyId);
      const agencyMap: Record<string, { id: string; name: string; type: string; totalLiability: number; deductions: Array<{ name: string; amount: number }> }> = {};
      const unlinked: Array<{ name: string; amount: number }> = [];
      for (const ded of allDeductions) {
        if (!ded.isActive || ded.isReferenceOnly) continue;
        let dedTotal = 0;
        for (const item of items) {
          const gross = parseFloat(item.grossPay || "0");
          if (ded.calculationType === "percentage") {
            dedTotal += gross * (parseFloat(ded.rate || "0") / 100);
          } else {
            dedTotal += parseFloat(ded.rate || "0");
          }
        }
        const agencyId = (ded as any).remittanceAgencyId;
        if (agencyId) {
          if (!agencyMap[agencyId]) {
            const agency = allAgencies.find(a => a.id === agencyId);
            agencyMap[agencyId] = { id: agencyId, name: agency?.name || agencyId, type: agency?.type || "unknown", totalLiability: 0, deductions: [] };
          }
          agencyMap[agencyId].totalLiability += dedTotal;
          agencyMap[agencyId].deductions.push({ name: ded.name, amount: dedTotal });
        } else {
          unlinked.push({ name: ded.name, amount: dedTotal });
        }
      }
      res.json({ agencies: Object.values(agencyMap), unlinked });
    } catch (err) {
      console.error("Agency liabilities error:", err);
      res.status(500).json({ message: "Failed to compute agency liabilities" });
    }
  });

