  app.post("/api/payroll-runs", requireRole("admin", "manager"), async (req, res) => {
    try {
      const { companyId } = req.body;
      const clientPayDate = req.body?.payDate as string | undefined;

      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ message: "Company not found" });

      // ── Require an active Pay Period Schedule ──────────────────────────────
      const companySchedules = await storage.getPayPeriodSchedules(companyId);
      const activeSchedules = companySchedules.filter(s => s.isActive);
      if (activeSchedules.length === 0) {
        return res.status(422).json({
          message: "No active Pay Period Schedule found for this company. " +
            "Go to Settings → Pay Period Schedules and activate a schedule before running payroll.",
        });
      }
      if (activeSchedules.length > 1) {
        return res.status(422).json({
          message: `${activeSchedules.length} active Pay Period Schedules found for this company. ` +
            "Only one schedule may be active at a time. Deactivate the extras in Settings → Pay Period Schedules.",
        });
      }
      const activeSchedule = activeSchedules[0];

      // ── Resolve period dates server-side from schedule + payDate ───────────
      if (!clientPayDate) return res.status(400).json({ message: "payDate is required" });
      const resolved = resolvePayPeriod(activeSchedule, clientPayDate);
      if (!resolved) {
        return res.status(400).json({
          message: "Could not resolve pay period from the active schedule and the provided payDate.",
        });
      }
      const periodStart = resolved.periodStart;
      const periodEnd = resolved.periodEnd;

      // ── Duplicate-period guard ──────────────────────────────────────────────
      // Reject if a finalized (processed/paid) run already exists for this
      // company + period.  The caller must void/delete the existing run first.
      const existingRunsForPeriod = (await storage.getPayrollRuns(companyId)).filter(r =>
        (r.status === "processed" || r.status === "paid") &&
        r.periodStart === periodStart &&
        r.periodEnd === periodEnd
      );
      if (existingRunsForPeriod.length > 0) {
        return res.status(409).json({
          message: `A finalized payroll run already exists for this company and pay period (${periodStart} – ${periodEnd}). ` +
            `Delete or void run #${existingRunsForPeriod[0].id.slice(0, 8)} before running payroll again for this period.`,
          conflictRunId: existingRunsForPeriod[0].id,
        });
      }

      const schedulePeriodsPerYear = periodsPerYearFromSchedule(activeSchedule.type);

      let entries = await storage.getTimeEntriesByDateRange(companyId, periodStart, periodEnd);
      // Strip volunteer-position shifts before any pay calculation
      const allPositionsForCreate = await storage.getPositions(companyId);
      const volunteerPosIds = new Set(allPositionsForCreate.filter((p: any) => p.isVolunteer).map((p: any) => p.id));
      if (volunteerPosIds.size > 0) {
        entries = entries.filter(e => !(e.positionId && volunteerPosIds.has(String(e.positionId))));
      }
      const allWorkers = await storage.getWorkers(companyId);
      // Treat null as active (handles workers added before the isActive column existed)
      const activeWorkers = allWorkers.filter(w => w.isActive !== false);
      const companyDeductions = await storage.getTaxesDeductions(companyId);

      const allSecondaryWageGroups = await storage.getSecondaryWageGroups(companyId);
      const wageGroupMap: Record<string, { hourlyRate: number; overtimeRate: number }> = {};
      for (const wg of allSecondaryWageGroups) {
        wageGroupMap[wg.id] = {
          hourlyRate: parseFloat(wg.hourlyRate || "0"),
          overtimeRate: parseFloat(wg.overtimeRate || "0"),
        };
      }

      const allRuns = await storage.getPayrollRuns(companyId);
      // YTD year anchored to payDate if provided, otherwise periodStart year.
      const previewYtdYear = clientPayDate
        ? new Date(clientPayDate + "T00:00:00").getFullYear()
        : new Date(periodStart).getFullYear();
      const previewYtdFloor = `${previewYtdYear}-01-01`;
      const priorRunsRaw = allRuns.filter(r =>
        (r.status === "processed" || r.status === "paid") &&
        r.periodEnd < periodStart &&
        r.periodEnd >= previewYtdFloor
      );
      const priorRuns = deduplicateByPeriod(priorRunsRaw);
      const existingYtdByWorker: Record<string, { gross: number; deductions: number; net: number }> = {};
      for (const worker of activeWorkers) {
        let ytdGross = 0, ytdDeductions = 0, ytdNet = 0;
        for (const pr of priorRuns) {
          const priorItems = await storage.getPayrollItems(pr.id);
          const workerItem = priorItems.find(i => i.workerId === worker.id);
          if (workerItem) {
            ytdGross += parseFloat(workerItem.grossPay || "0");
            ytdDeductions += parseFloat(workerItem.deductions || "0");
            ytdNet += parseFloat(workerItem.netPay || "0");
          }
        }
        existingYtdByWorker[worker.id] = { gross: ytdGross, deductions: ytdDeductions, net: ytdNet };
      }

      const otMultiplier = Number(company.overtimeMultiplier || 1.5);

      // ── Load worker payment methods to set per-worker paymentMethod ────────
      const allWorkerPayMethods = await storage.getPayMethods();
      const workerPayMethodMap: Record<string, string> = {};
      for (const pm of allWorkerPayMethods) {
        const wId = (pm as any).workerId;
        if (!wId) continue;
        if (pm.isPrimary || !workerPayMethodMap[wId]) {
          const mt = (pm.methodType || "check").toLowerCase();
          workerPayMethodMap[wId] = mt === "direct_deposit" || mt === "ach" ? "ach" : mt;
        }
      }

      // ── Load approved commissions for this period ────────────────────────
      const { commissions: createCommissionsTable } = await import("../shared/schema.js");
      const createPeriodCommissions = await db.select().from(createCommissionsTable).where(
        and(
          eq(createCommissionsTable.companyId, companyId),
          eq(createCommissionsTable.status, "approved"),
          gte(createCommissionsTable.earnedDate, periodStart),
          lte(createCommissionsTable.earnedDate, periodEnd)
        )
      );
      const createCommByWorker: Record<string, typeof createPeriodCommissions> = {};
      for (const c of createPeriodCommissions) {
        if (!createCommByWorker[c.workerId]) createCommByWorker[c.workerId] = [];
        createCommByWorker[c.workerId].push(c);
      }

      const items: any[] = [];
      let totalGross = 0, totalNet = 0, totalHoursSum = 0, totalOT = 0;
      const _checkNumStart2 = await db.transaction(async (tx) => {
        await tx.execute(sql`SELECT pg_advisory_xact_lock(abs(hashtext(${companyId}))::bigint)`);
        const _r2 = await tx.execute(sql`SELECT next_check_number FROM companies WHERE id = ${companyId} FOR UPDATE`);
        const _s2 = Number((((_r2 as any).rows || (_r2 as any))[0])?.next_check_number || 1);
        await tx.execute(sql`UPDATE companies SET next_check_number = ${_s2 + activeWorkers.length} WHERE id = ${companyId}`);
        return _s2;
      });
      let checkNum = _checkNumStart2;

      for (const worker of activeWorkers) {
        const workerEntries = entries.filter(e => e.workerId === worker.id);

        // ── Diagnostic: log raw DB pay_category for every entry before fallback ──
        console.log(`[PAYROLL] CREATE ${worker.firstName} ${worker.lastName} (id=${worker.id}): ${workerEntries.length} entries`);
        for (const e of workerEntries) {
          const rawCat = (e as any).payCategory;
          console.log(`[PAYROLL] RAW entry date=${e.date} pay_category_db=${JSON.stringify(rawCat)} totalHours=${e.totalHours} overtimeHours=${e.overtimeHours}`);
        }

        const defaultRate = parseFloat(worker.payRate || "0");

        // ── Commission earnings (CREATE) ──────────────────────────────────────
        const createWorkerComms = createCommByWorker[worker.id] || [];
        const createCommPay = createWorkerComms.reduce((sum, c) => sum + parseFloat(c.amount || "0"), 0);

        // ── Unified calculator: all 15 pay categories, both hourly and salary ──
        // This is the ONLY place payroll math runs in the create/draft route.
        const createCalcResult = calculateWorkerPay(
          { id: worker.id, payType: worker.payType || "hourly", payRate: worker.payRate || "0" },
          workerEntries.map(e => ({
            workerId: e.workerId,
            totalHours: e.totalHours || "0",
            overtimeHours: e.overtimeHours || "0",
            doubleTimeHours: (e as any).doubleTimeHours || "0",
            payCategory: (e as any).payCategory,
            overridePayRate: (e as any).overridePayRate,
            wageGroupId: e.wageGroupId,
            tipsAmount: (e as any).tipsAmount,
          })),
          {
            overtimeMultiplier: otMultiplier,
            periodsPerYear: schedulePeriodsPerYear,
            wageGroups: wageGroupMap,
            commissionPay: createCommPay,
          }
        );
        let regHrs             = createCalcResult.regularHours;
        let otHrs              = createCalcResult.overtimeHours;
        let dtHrs              = createCalcResult.doubleTimeHours;
        let regPay             = createCalcResult.regularPay;
        let otPay              = createCalcResult.overtimePay;
        let dtPay              = createCalcResult.doubleTimePay;
        let createCommHrsTotal = createCalcResult.commissionHours;
        let createCommHrlyPay  = createCalcResult.commissionHourlyPay;
        let grossPay           = createCalcResult.grossPay;
        console.log(`[PAYROLL] CREATE ${worker.payType === "salary" ? "SALARY" : "HOURLY"} workerId=${worker.id} regHrs=${regHrs.toFixed(2)} commHrs=${createCommHrsTotal.toFixed(2)} salaryPay=${createCalcResult.salaryPay.toFixed(2)} commPay=${createCommPay.toFixed(2)} grossPay=${grossPay.toFixed(2)}`);

        const totalHrs = regHrs + otHrs + dtHrs + createCommHrsTotal;

        const compTypeCreate = (worker as any).compensationType || "hourly";
        const isCommissionOnlyCreate = compTypeCreate === "commission";
        // Skip workers with no hours unless they have salary pay type or are commission-only
        if (totalHrs === 0 && worker.payType !== "salary" && !isCommissionOnlyCreate) continue;
        // Commission-only workers with no commissions this period also skip
        if (isCommissionOnlyCreate && createCommPay === 0 && totalHrs === 0) continue;

        const isContractor = worker.workerType === "contractor";
        const workerGroup2 = (worker as any).workerGroup || (isContractor ? "hourly_contractor" : "hourly_employee");
        const isContractorGroup2 = workerGroup2 === "hourly_contractor" || workerGroup2 === "invoiced_contractor";
        const isVolunteer2 = workerGroup2 === "volunteer";

        if (isVolunteer2) {
          console.log(`[PAYROLL-DRAFT] Skipping volunteer worker: ${worker.firstName} ${worker.lastName} (workerGroup="${workerGroup2}")`);
          continue;
        }

        const workerDeds = (isContractor || isContractorGroup2) ? [] : companyDeductions.filter(d => {
          if (!d.isActive || d.isEmployerPaid || d.isReferenceOnly) return false;
          const appliesTo = d.appliesTo || "all";
          if (appliesTo === "contractor") return false;
          const nl = d.name.toLowerCase();
          if (nl.includes("se tax") || nl.includes("self-employment") || nl.includes("self employment")) return false;
          return true;
        });

        const ytd = existingYtdByWorker[worker.id] || { gross: 0, deductions: 0, net: 0 };
        let totalDeductions = 0;
        for (const ded of workerDeds) {
          if (ded.calculationType === "percentage") {
            if (ded.maxAmount) {
              const wageCap = parseFloat(ded.maxAmount);
              const remainingCap = Math.max(0, wageCap - ytd.gross);
              const base = Math.min(grossPay, remainingCap);
              totalDeductions += base * (parseFloat(ded.rate || "0") / 100);
            } else {
              totalDeductions += grossPay * (parseFloat(ded.rate || "0") / 100);
            }
          } else {
            totalDeductions += parseFloat(ded.rate || "0");
          }
        }

        const netPay = grossPay - totalDeductions;

        totalGross += grossPay;
        totalNet += netPay;
        totalHoursSum += totalHrs;
        totalOT += otHrs;

        const resolvedPaymentMethod = workerPayMethodMap[worker.id] || "check";
        items.push({
          workerId: worker.id,
          regularHours: regHrs.toFixed(2),
          overtimeHours: otHrs.toFixed(2),
          doubleTimeHours: dtHrs.toFixed(2),
          // regularPay: salary base kept here for backward compat; salaryPay column is additional detail
          regularPay: (regPay + createCalcResult.salaryPay).toFixed(2),
          overtimePay: otPay.toFixed(2),
          doubleTimePay: dtPay.toFixed(2),
          grossPay: grossPay.toFixed(2),
          deductions: totalDeductions.toFixed(2),
          netPay: netPay.toFixed(2),
          payRate: defaultRate.toFixed(2),
          payType: worker.payType || "hourly",
          paymentMethod: resolvedPaymentMethod,
          checkNumber: String(checkNum++),
          ytdGross: (ytd.gross + grossPay).toFixed(2),
          ytdDeductions: (ytd.deductions + totalDeductions).toFixed(2),
          ytdNet: (ytd.net + netPay).toFixed(2),
          commissionPay: createCommPay > 0 ? createCommPay.toFixed(2) : undefined,
          commissionHours: createCommHrsTotal > 0 ? createCommHrsTotal.toFixed(2) : "0",
          commissionHourlyPay: createCommHrlyPay > 0 ? createCommHrlyPay.toFixed(2) : "0",
          // ── All 15 categories (Task 2) ────────────────────────────────────
          salaryPay: createCalcResult.salaryPay > 0 ? createCalcResult.salaryPay.toFixed(2) : "0",
          bonusPay: createCalcResult.bonusPay > 0 ? createCalcResult.bonusPay.toFixed(2) : "0",
          tipsPay: createCalcResult.tipsPay > 0 ? createCalcResult.tipsPay.toFixed(2) : "0",
          reimburseAmount: createCalcResult.reimburseAmount > 0 ? createCalcResult.reimburseAmount.toFixed(2) : "0",
          ptoHours: createCalcResult.ptoHours > 0 ? createCalcResult.ptoHours.toFixed(2) : "0",
          ptoPay: createCalcResult.ptoPay > 0 ? createCalcResult.ptoPay.toFixed(2) : "0",
          sickHours: createCalcResult.sickHours > 0 ? createCalcResult.sickHours.toFixed(2) : "0",
          sickPay: createCalcResult.sickPay > 0 ? createCalcResult.sickPay.toFixed(2) : "0",
          holidayHours: createCalcResult.holidayHours > 0 ? createCalcResult.holidayHours.toFixed(2) : "0",
          holidayPay: createCalcResult.holidayPay > 0 ? createCalcResult.holidayPay.toFixed(2) : "0",
          unpaidHours: createCalcResult.unpaidHours > 0 ? createCalcResult.unpaidHours.toFixed(2) : "0",
          unpaidDeduction: createCalcResult.unpaidDeduction > 0 ? createCalcResult.unpaidDeduction.toFixed(2) : "0",
        });
      }

      // Auto-assign default funding account if available
      const allFundingAccts = await storage.getFundingAccounts(companyId);
      const defaultFundingAcct = allFundingAccts.find(a => (a as any).isDefault && a.active !== false && a.allowForPayroll !== false)
        || allFundingAccts.find(a => a.active !== false && a.allowForPayroll !== false) // fallback: first payroll-eligible account
        || null;

      const payrollRun = await storage.createPayrollRun({
        companyId,
        periodStart,
        periodEnd,
        payDate: clientPayDate || null,
        status: "processed",
        totalGross: totalGross.toFixed(2),
        totalNet: totalNet.toFixed(2),
        totalHours: totalHoursSum.toFixed(2),
        totalOvertimeHours: totalOT.toFixed(2),
        workerCount: items.length,
        processedAt: new Date(),
        fundingAccountId: defaultFundingAcct?.id || null,
        needsRecalculation: false,
      } as any);

      for (const item of items) {
        await storage.createPayrollItem({ payrollRunId: payrollRun.id, ...item });
      }

      // Mark approved commissions in this period as paid
      const createCommIdsToMark: string[] = [];
      for (const wComms of Object.values(createCommByWorker)) {
        for (const c of wComms) createCommIdsToMark.push(c.id);
      }
      if (createCommIdsToMark.length > 0) {
        await db.update(createCommissionsTable)
          .set({ status: "paid", payrollRunId: payrollRun.id, paidAt: new Date() } as any)
          .where(inArray(createCommissionsTable.id, createCommIdsToMark));
      }

      await db.execute(sql`UPDATE companies SET next_check_number = GREATEST(next_check_number, ${checkNum}) WHERE id = ${companyId}`);

      res.status(201).json(payrollRun);
    } catch (error: any) {
      console.error("Payroll processing error:", error);
      res.status(500).json({ message: safeErrorMessage(error, "Failed to process payroll") });
    }
  });

  app.patch("/api/payroll-runs/:id", requireRole("admin", "manager"), async (req, res) => {
    try {
      const existing = await storage.getPayrollRun(req.params.id as string);
      if (!existing) return res.status(404).json({ message: "Payroll run not found" });
      // Company ownership guard
      const actingUser = await storage.getUser(req.session.userId!);
      const isTenant = !isPlatformUser(actingUser?.role) && !!actingUser?.companyId;
      if (isTenant && existing.companyId !== actingUser!.companyId) {
        return res.status(403).json({ message: "Forbidden: payroll run belongs to a different company" });
      }
      const lockedCheck = existing.lockedAt || existing.isLocked;
      if (lockedCheck) {
        const allowed = ["achStatus", "achBatchId", "achSubmittedAt", "achSettledAt", "fundingAccountId"];
        const attempted = Object.keys(req.body).filter(k => !allowed.includes(k));
        if (attempted.length > 0) {
          return res.status(409).json({ message: "Payroll run is locked and cannot be modified" });
        }
      }
      const run = await storage.updatePayrollRun(req.params.id as string, req.body);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      res.json(run);
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Failed to update payroll run" });
    }
  });

