  // ── Proposal Download ─────────────────────────────────────────────────────
  app.get("/api/contractor-proposals/:id/download", requireAuth, async (req, res) => {
    try {
      const propRes = await db.execute(sql`SELECT * FROM contractor_proposals WHERE id = ${req.params.id}`);
      if (!propRes.rows[0]) return res.status(404).json({ message: "Proposal not found" });
      const prop = propRes.rows[0] as any;
      const user = await storage.getUser(req.session.userId!);
      const isPlatform = (user?.role || "").startsWith("platform_");
      const isAdmin = isPlatform || (user?.role || "").startsWith("tenant_") || user?.role === "admin" || user?.role === "manager";
      const wRes = await db.execute(sql`SELECT worker_id FROM users WHERE id = ${req.session.userId}`);
      const workerId = (wRes.rows[0] as any)?.worker_id;
      // Non-admin must own the proposal
      if (!isAdmin && prop.contractor_id !== workerId) return res.status(403).json({ message: "Access denied" });
      // Admin must be scoped to their company (platform admins bypass)
      if (isAdmin && !isPlatform && user?.companyId && prop.company_id !== user.companyId) {
        return res.status(403).json({ message: "Access denied: proposal belongs to another company" });
      }
      const lineItemsRes = await db.execute(sql`SELECT * FROM proposal_line_items WHERE proposal_id = ${req.params.id}`);
      const exportData = { ...prop, lineItems: lineItemsRes.rows, exportedAt: new Date().toISOString() };
      const filename = `proposal-${(prop.proposal_number || req.params.id).replace(/[^a-z0-9]/gi, "_")}.json`;
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.setHeader("Content-Type", "application/json");
      res.json(exportData);
    } catch (e: any) { res.status(500).json({ message: "Failed to download proposal: " + e.message }); }
  });

  // GET /api/contractor-proposals/:id/pdf — on-demand PDF generation (or serve stored DMS copy)
  app.get("/api/contractor-proposals/:id/pdf", requireAuth, async (req, res) => {
    try {
      const propRes = await db.execute(sql`SELECT * FROM contractor_proposals WHERE id = ${req.params.id}`);
      const prop = firstRow<ProposalRow>(propRes);
      if (!prop) return res.status(404).json({ message: "Proposal not found" });
      const user = await storage.getUser(req.session.userId!);
      const isPlatform = (user?.role || "").startsWith("platform_");
      const isAdmin = isPlatform || (user?.role || "").startsWith("tenant_") || user?.role === "admin" || user?.role === "manager";
      const wRes = await db.execute(sql`SELECT worker_id FROM users WHERE id = ${req.session.userId}`);
      const workerRow = firstRow<{ worker_id: string | null }>(wRes);
      const workerId = workerRow?.worker_id ?? null;
      if (!isAdmin && prop.contractor_id !== workerId) return res.status(403).json({ message: "Access denied" });
      if (isAdmin && !isPlatform && user?.companyId && prop.company_id !== user.companyId) return res.status(403).json({ message: "Access denied: proposal belongs to another company" });

      // Check if a stored PDF already exists in DMS
      const existingPdf = await db.execute(sql`SELECT file_path, file_name FROM dam_documents WHERE linked_entity_type = 'proposal' AND linked_entity_id = ${req.params.id} AND mime_type = 'application/pdf' ORDER BY created_at DESC LIMIT 1`);
      const stored = firstRow<{ file_path: string | null; file_name: string | null }>(existingPdf);
      let filePath: string | null = null;
      if (stored?.file_path) {
        filePath = stored.file_path;
      } else {
        // Generate on demand
        filePath = await generateProposalPdf(req.params.id, prop, req.session.userId!);
      }

      if (!filePath) return res.status(500).json({ message: "Failed to generate proposal PDF" });
      // Reuse the same traversal-safe resolver that hardens
      // /api/dam-documents/:id/download. Refuses anything that escapes the
      // project root, even if the DB-stored file_path was tampered with.
      const { resolveDamFilePath } = await import("./dam-paths");
      const root = process.cwd();
      const resolved = resolveDamFilePath(String(filePath), root);
      if (!resolved) return res.status(400).json({ message: "Invalid PDF file path" });
      if (!fs.existsSync(resolved)) return res.status(404).json({ message: "PDF file not found on disk" });
      const pdfFileName = stored?.file_name ? String(stored.file_name) : path.basename(resolved);
      res.setHeader("Content-Type", "application/pdf");
      // inline so the UI "Preview PDF" action renders in the browser tab
      // rather than triggering a download. Callers that want to download
      // can use the link's `download` attribute.
      res.setHeader("Content-Disposition", `inline; filename="${pdfFileName.replace(/"/g, "")}"`);
      res.sendFile(resolved);
    } catch (e: any) { res.status(500).json({ message: "Failed to serve proposal PDF: " + e.message }); }
  });

  // ── Payment Download ──────────────────────────────────────────────────────
  app.get("/api/contractor-payments/:id/download", requireAuth, async (req, res) => {
    try {
      const payRes = await db.execute(sql`SELECT * FROM contractor_payments WHERE id = ${req.params.id}`);
      if (!payRes.rows[0]) return res.status(404).json({ message: "Payment not found" });
      const pay = payRes.rows[0] as any;
      const user = await storage.getUser(req.session.userId!);
      const isPlatform = (user?.role || "").startsWith("platform_");
      const isAdmin = isPlatform || (user?.role || "").startsWith("tenant_") || user?.role === "admin" || user?.role === "manager";
      const wRes = await db.execute(sql`SELECT worker_id FROM users WHERE id = ${req.session.userId}`);
      const workerId = (wRes.rows[0] as any)?.worker_id;
      // Non-admin must own the payment record
      if (!isAdmin && pay.contractor_id !== workerId) return res.status(403).json({ message: "Access denied" });
      // Admin must be scoped to their company (platform admins bypass)
      if (isAdmin && !isPlatform && user?.companyId && pay.company_id !== user.companyId) {
        return res.status(403).json({ message: "Access denied: payment belongs to another company" });
      }
      const exportData = { ...pay, exportedAt: new Date().toISOString() };
      const filename = `payment-receipt-${req.params.id.slice(0, 8)}.json`;
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.setHeader("Content-Type", "application/json");
      res.json(exportData);
    } catch (e: any) { res.status(500).json({ message: "Failed to download payment: " + e.message }); }
  });

  // ── Invoice: Request Override ─────────────────────────────────────────────
  app.post("/api/contractor-invoices/:id/request-override", requireAuth, async (req, res) => {
    try {
      const inv = await storage.getContractorInvoice(req.params.id);
      if (!inv) return res.status(404).json({ message: "Not found" });
      const user = await storage.getUser(req.session.userId!);
      if (user?.workerId !== inv.contractorId) return res.status(403).json({ message: "Not your invoice" });
      if (["paid", "rejected", "cancelled"].includes(inv.status || "")) return res.status(400).json({ message: `Cannot request override on a ${inv.status} invoice` });
      const { overrideReason, overrideAmount } = req.body;
      if (!overrideReason) return res.status(400).json({ message: "Override reason is required" });
      await db.execute(sql`
        UPDATE contractor_invoices SET
          override_requested = TRUE,
          override_reason = ${overrideReason},
          override_amount = ${overrideAmount || null},
          override_requested_at = NOW(),
          updated_at = NOW()
        WHERE id = ${req.params.id}
      `);
      await storage.createExpenseApprovalAction({
        objectType: "contractor_invoice", objectId: req.params.id, actionType: "override_requested",
        actorUserId: req.session.userId, companyId: inv.companyId,
        note: overrideReason,
      });
      // Notify admin/manager of override request via contractor notifications
      createContractorNotification({ companyId: inv.companyId, notificationType: "invoice_override_requested", title: `Override Requested: Invoice #${(inv as any).invoiceNumber || req.params.id.slice(0, 8)}`, body: overrideReason || "A contractor has requested a payment override for an invoice.", entityType: "invoice", entityId: req.params.id, actionUrl: `/app/contractor-hub?section=invoices&id=${req.params.id}` }).catch(() => {});
      // Notify admin/manager of override request
      try {
        const { sendContractEventEmail } = await import("./notifications.js");
        const baseUrl = process.env.APP_BASE_URL || "";
        const invRef = (inv as any).invoiceNumber || req.params.id;
        await db.execute(sql`INSERT INTO notifications (company_id, user_id, type, title, message, action_url, is_read) SELECT ${inv.companyId}, u.id, 'override_requested', ${"Override Requested: " + invRef}, ${overrideReason}, ${baseUrl + "/app/contractor-hub"}, false FROM users u WHERE u.company_id = ${inv.companyId} AND u.role IN ('admin','manager','tenant_admin','tenant_owner') LIMIT 5`);
        const adminsRes = await db.execute(sql`SELECT u.email, u.username AS name FROM users u WHERE u.company_id = ${inv.companyId} AND u.role IN ('admin','manager','tenant_admin') LIMIT 3`);
        const overrideAmt = overrideAmount ? parseFloat(String(overrideAmount)) : null;
        for (const admin of adminsRes.rows as any[]) {
          sendContractEventEmail({ event: "override_requested", recipientName: admin.name || "Admin", email: admin.email, contractTitle: invRef, entityId: req.params.id, entityType: "invoice", amount: overrideAmt, note: overrideReason, actionUrl: `${baseUrl}/app/contractor-hub` }).catch(() => {});
        }
      } catch (notifErr) { console.error("[Invoice] Notify override failed:", notifErr); }
      res.json({ message: "Override request submitted" });
    } catch (e: any) { res.status(500).json({ message: "Failed to submit override request: " + e.message }); }
  });

  // ── DAM Documents ─────────────────────────────────────────────────────────
  app.get("/api/dam-documents", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const { companyId, linkedEntityId } = req.query as Record<string, string>;
      const isAdmin = user?.role === "admin" || user?.role === "manager" || (user?.role || "").startsWith("tenant_") || (user?.role || "").startsWith("platform_");
      let result;
      if (isAdmin) {
        // Admins filter by company; optionally by linked entity
        const cid = companyId || user?.companyId;
        result = await db.execute(sql`
          SELECT * FROM dam_documents
          WHERE is_archived = FALSE
            AND (company_id = ${cid} OR (company_id IS NULL AND worker_id IN (SELECT id FROM workers WHERE company_id = ${cid})))
            ${linkedEntityId ? sql`AND linked_entity_id = ${linkedEntityId}` : sql``}
          ORDER BY created_at DESC
        `);
      } else {
        // Contractors only see their own documents — workerId always from session
        const wRes = await db.execute(sql`SELECT worker_id FROM users WHERE id = ${req.session.userId}`);
        const wId = (wRes.rows[0] as any)?.worker_id;
        if (!wId) return res.json([]);
        result = await db.execute(sql`SELECT * FROM dam_documents WHERE worker_id = ${wId} AND is_archived = FALSE ORDER BY created_at DESC`);
      }
      res.json(result.rows);
    } catch (e: any) { res.status(500).json({ message: "Failed to fetch documents" }); }
  });

  app.get("/api/dam-documents/:id", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const wRes = await db.execute(sql`SELECT worker_id FROM users WHERE id = ${req.session.userId}`);
      const workerId = (wRes.rows[0] as any)?.worker_id;
      const isAdmin = user?.role === "admin" || user?.role === "manager" || (user?.role || "").startsWith("tenant_") || (user?.role || "").startsWith("platform_");
      const result = await db.execute(sql`SELECT * FROM dam_documents WHERE id = ${req.params.id}`);
      if (!result.rows[0]) return res.status(404).json({ message: "Document not found" });
      const doc = result.rows[0] as any;
      // Ownership: admin sees company docs; contractor sees own
      if (!isAdmin && doc.worker_id !== workerId) return res.status(403).json({ message: "Access denied" });
      if (isAdmin && user?.companyId && doc.company_id && doc.company_id !== user.companyId && !(user?.role || "").startsWith("platform_")) return res.status(403).json({ message: "Access denied" });
      await db.execute(sql`INSERT INTO dam_document_access_logs (document_id, accessed_by_user_id, accessed_by_worker_id, action) VALUES (${req.params.id}, ${req.session.userId}, ${workerId || null}, 'view')`).catch(() => {});
      res.json(doc);
    } catch (e: any) { res.status(500).json({ message: "Failed to fetch document" }); }
  });

  app.post("/api/dam-documents", requireAuth, documentUpload.single("file"), async (req: any, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const isAdmin = user?.role === "admin" || user?.role === "manager" || (user?.role || "").startsWith("tenant_") || (user?.role || "").startsWith("platform_");
      const isPlatform = (user?.role || "").startsWith("platform_");
      const wRes = await db.execute(sql`SELECT worker_id FROM users WHERE id = ${req.session.userId}`);
      const sessionWorkerId = (wRes.rows[0] as any)?.worker_id || null;
      let workerId: number | null;
      if (isAdmin && req.body.workerId) {
        // Admin may specify a target worker, but must validate they belong to the same company
        const workerCheck = await db.execute(sql`SELECT id, company_id FROM workers WHERE id = ${req.body.workerId}`);
        if (!workerCheck.rows[0]) return res.status(404).json({ message: "Worker not found" });
        const targetWorker = workerCheck.rows[0] as any;
        if (!isPlatform && user?.companyId && targetWorker.company_id !== user.companyId) return res.status(403).json({ message: "Access denied: worker does not belong to your company" });
        workerId = targetWorker.id;
      } else {
        // Non-admins (and admins without an override) upload for themselves
        workerId = sessionWorkerId;
      }
      const { title, description, documentType, tags, linkedEntityType, linkedEntityId, isPublic, ownerType } = req.body;
      const filePath = req.file ? `/uploads/${req.file.filename}` : req.body.filePath;
      if (!filePath) return res.status(400).json({ message: "File or filePath required" });
      const result = await db.execute(sql`
        INSERT INTO dam_documents (company_id, worker_id, owner_type, document_type, title, description, file_path, file_name, file_type, file_size, mime_type, tags, linked_entity_type, linked_entity_id, is_public, uploaded_by_user_id)
        VALUES (${user?.companyId || null}, ${workerId}, ${ownerType || "worker"}, ${documentType || "general"}, ${title || req.file?.originalname || "Document"}, ${description || null}, ${filePath}, ${req.file?.originalname || null}, ${req.file?.mimetype?.split("/")[0] || null}, ${req.file?.size || null}, ${req.file?.mimetype || null}, ${tags || null}, ${linkedEntityType || null}, ${linkedEntityId || null}, ${isPublic === "true" || false}, ${req.session.userId})
        RETURNING *
      `);
      res.status(201).json(result.rows[0]);
    } catch (e: any) { res.status(500).json({ message: "Failed to upload document: " + e.message }); }
  });

  app.get("/api/dam-documents/:id/download", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const wRes = await db.execute(sql`SELECT worker_id FROM users WHERE id = ${req.session.userId}`);
      const workerId = (wRes.rows[0] as any)?.worker_id;
      const isAdmin = user?.role === "admin" || user?.role === "manager" || (user?.role || "").startsWith("tenant_") || (user?.role || "").startsWith("platform_");
      const result = await db.execute(sql`SELECT * FROM dam_documents WHERE id = ${req.params.id}`);
      if (!result.rows[0]) return res.status(404).json({ message: "Document not found" });
      const doc = result.rows[0] as any;
      if (!isAdmin && doc.worker_id !== workerId) return res.status(403).json({ message: "Access denied" });
      if (isAdmin && user?.companyId && doc.company_id && doc.company_id !== user.companyId && !(user?.role || "").startsWith("platform_")) return res.status(403).json({ message: "Access denied" });
      await db.execute(sql`INSERT INTO dam_document_access_logs (document_id, accessed_by_user_id, accessed_by_worker_id, action) VALUES (${req.params.id}, ${req.session.userId}, ${workerId || null}, 'download')`).catch(() => {});

      // Stream the file directly so the browser receives the PDF/binary
      // instead of a JSON descriptor. Resolves an absolute path safely under
      // the project root and refuses anything that escapes it.
      const fs = await import("fs");
      const path = await import("path");
      const { resolveDamFilePath } = await import("./dam-paths");
      const root = process.cwd();
      const resolved = resolveDamFilePath(String(doc.file_path || ""), root);
      if (!resolved) return res.status(400).json({ message: "Invalid file path" });
      if (!fs.existsSync(resolved)) return res.status(404).json({ message: "File missing on disk" });
      const fileName = String(doc.file_name || path.basename(resolved));
      if (doc.mime_type) res.setHeader("Content-Type", String(doc.mime_type));
      res.setHeader("Content-Disposition", `inline; filename="${fileName.replace(/"/g, "")}"`);
      return res.sendFile(resolved);
    } catch (e: any) { res.status(500).json({ message: "Failed to initiate download" }); }
  });

