  app.post("/api/contractor-templates", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const { name, description, templateType, industry, bodyJson, defaultPaymentTerms, defaultScopeTemplate, defaultAssumptions, defaultExclusions, defaultWarranty, isGlobal, isDefault, layoutVariant, workTypeTags, isActive } = req.body;
      if (!name) return res.status(400).json({ message: "name is required" });
      const user = await storage.getUser(req.session.userId!);
      const isPlatformAdmin = user?.role === "platform_super_admin" || user?.role === "platform_admin";
      // Only platform_super_admin / platform_admin can create global templates
      const globalFlag = isPlatformAdmin && isGlobal === true;
      // Block other platform roles (sales, support, billing, auditor) from creating global templates
      if (isGlobal === true && !isPlatformAdmin) {
        return res.status(403).json({ message: "platform_super_admin or platform_admin role required to create global templates" });
      }
      // Enforce single-default: if creating as default, clear other defaults for this company + type
      if (isDefault) {
        const clearCid = user?.companyId || null;
        const clearType = templateType || "proposal";
        if (clearCid) {
          await db.execute(sql`UPDATE contractor_templates SET is_default = FALSE WHERE company_id = ${clearCid} AND template_type = ${clearType} AND is_default = TRUE`);
        } else if (globalFlag) {
          await db.execute(sql`UPDATE contractor_templates SET is_default = FALSE WHERE company_id IS NULL AND template_type = ${clearType} AND is_default = TRUE`);
        }
      }
      const result = await db.execute(sql`
        INSERT INTO contractor_templates (company_id, template_type, name, description, industry, body_json, default_payment_terms, default_scope_template, default_assumptions, default_exclusions, default_warranty, is_global, is_default, layout_variant, work_type_tags, is_active, created_by_user_id)
        VALUES (${user?.companyId || null}, ${templateType || "proposal"}, ${name}, ${description || null}, ${industry || null}, ${bodyJson || null}, ${defaultPaymentTerms || null}, ${defaultScopeTemplate || null}, ${defaultAssumptions || null}, ${defaultExclusions || null}, ${defaultWarranty || null}, ${globalFlag}, ${isDefault || false}, ${layoutVariant || "standard"}, ${workTypeTags || null}, ${isActive !== false}, ${req.session.userId})
        RETURNING *
      `);
      res.status(201).json(result.rows[0]);
    } catch (e: any) { res.status(500).json({ message: "Failed to create template: " + e.message }); }
  });

  app.patch("/api/contractor-templates/:id", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      // Verify template ownership before mutating
      const user = await storage.getUser(req.session.userId!);
      const isPlatformAdmin = user?.role === "platform_super_admin" || user?.role === "platform_admin";
      const tplRes = await db.execute(sql`SELECT id, company_id, is_global FROM contractor_templates WHERE id = ${req.params.id}`);
      if (!tplRes.rows[0]) return res.status(404).json({ message: "Template not found" });
      const tpl = tplRes.rows[0] as any;
      // Only platform_super_admin / platform_admin can mutate global/platform templates
      if (!tpl.company_id || tpl.is_global) {
        if (!isPlatformAdmin) return res.status(403).json({ message: "platform_super_admin or platform_admin role required to modify global templates" });
      } else {
        // For company-owned templates, any platform admin or the owning tenant can edit
        const isAnyPlatform = (user?.role || "").startsWith("platform_");
        if (!isAnyPlatform && tpl.company_id !== user?.companyId) return res.status(403).json({ message: "Access denied" });
      }
      const { name, description, templateType, industry, bodyJson, defaultPaymentTerms, defaultScopeTemplate, defaultAssumptions, defaultExclusions, defaultWarranty, isActive, isDefault, layoutVariant, workTypeTags } = req.body;
      // Enforce single-default: if setting isDefault=true, clear other defaults for this company + type
      if (isDefault === true) {
        const clearType = templateType || tpl.template_type || "proposal";
        if (tpl.company_id) {
          await db.execute(sql`UPDATE contractor_templates SET is_default = FALSE WHERE company_id = ${tpl.company_id} AND template_type = ${clearType} AND id <> ${req.params.id} AND is_default = TRUE`);
        } else if (tpl.is_global) {
          await db.execute(sql`UPDATE contractor_templates SET is_default = FALSE WHERE company_id IS NULL AND template_type = ${clearType} AND id <> ${req.params.id} AND is_default = TRUE`);
        }
      }
      const result = await db.execute(sql`
        UPDATE contractor_templates SET
          name = COALESCE(${name ?? null}, name),
          description = COALESCE(${description ?? null}, description),
          template_type = COALESCE(${templateType ?? null}, template_type),
          industry = COALESCE(${industry ?? null}, industry),
          body_json = COALESCE(${bodyJson ?? null}, body_json),
          default_payment_terms = COALESCE(${defaultPaymentTerms ?? null}, default_payment_terms),
          default_scope_template = COALESCE(${defaultScopeTemplate ?? null}, default_scope_template),
          default_assumptions = COALESCE(${defaultAssumptions ?? null}, default_assumptions),
          default_exclusions = COALESCE(${defaultExclusions ?? null}, default_exclusions),
          default_warranty = COALESCE(${defaultWarranty ?? null}, default_warranty),
          is_active = COALESCE(${isActive != null ? isActive : null}, is_active),
          is_default = COALESCE(${isDefault != null ? isDefault : null}, is_default),
          layout_variant = COALESCE(${layoutVariant ?? null}, layout_variant),
          work_type_tags = COALESCE(${workTypeTags ?? null}, work_type_tags),
          updated_at = NOW()
        WHERE id = ${req.params.id}
        RETURNING *
      `);
      if (!result.rows[0]) return res.status(404).json({ message: "Template not found" });
      res.json(result.rows[0]);
    } catch (e: any) { res.status(500).json({ message: "Failed to update template: " + e.message }); }
  });

